import { PrismaClient } from '@prisma/client'
import { differenceInHours, startOfMonth, endOfMonth, min, max, differenceInMinutes } from 'date-fns'

const prisma = new PrismaClient()

async function main() {
    const now = new Date('2026-03-16T23:30:00Z') // March 16 23:30 UTC
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1)
    const lastDay = endOfMonth(now)
    const referenceEnd = now

    let log = '--- DIAGNOSTICO DISPONIBILIDADE ---\n'
    log += `Now (Ref): ${now.toISOString()}\n`
    log += `Periodo: ${firstDay.toISOString()} a ${lastDay.toISOString()}\n`

    const veiculos = await prisma.veiculo.findMany({
        where: { codigoInterno: 'FRT-003' },
        include: {
            os: {
                where: {
                    dataAbertura: { lte: lastDay },
                    OR: [
                        { dataConclusao: null },
                        { dataConclusao: { gte: firstDay } }
                    ],
                    status: { in: ['ABERTA', 'PLANEJADA', 'EM_EXECUCAO', 'CONCLUIDA'] }
                }
            }
        }
    })

    log += `Veiculos encontrados: ${veiculos.length}\n`
    if (veiculos.length > 0) {
        const v = veiculos[0]
        log += `Veiculo: ${v.codigoInterno} Status: ${v.status}\n`
        log += `O.S. Vinculadas: ${v.os.length}\n`

        let totalDowntimeHours = 0
        v.os.forEach((os: any, i: number) => {
            const osStart = new Date(os.dataAbertura)
            const osEnd = os.dataConclusao ? new Date(os.dataConclusao) : referenceEnd

            const startCalculo = max([osStart, firstDay])
            const endCalculo = min([osEnd, referenceEnd])

            const minutes = differenceInMinutes(endCalculo, startCalculo)
            log += `OS #${i+1}: ${os.numeroOS || 'S/N'}\n`
            log += `  Status: ${os.status}\n`
            log += `  Data Abertura: ${os.dataAbertura.toISOString()}\n`
            log += `  Start Calc: ${startCalculo.toISOString()}\n`
            log += `  End Calc: ${endCalculo.toISOString()}\n`
            log += `  Minutes: ${minutes}\n`

            if (minutes > 0) totalDowntimeHours += (minutes / 60)
        })

        const totalHoursInPeriodMath = Math.max(1, differenceInMinutes(referenceEnd, firstDay) / 60)
        const availability = Math.max(0, ((totalHoursInPeriodMath - totalDowntimeHours) / totalHoursInPeriodMath) * 100)

        log += `Total Downtime (H): ${totalDowntimeHours}\n`
        log += `Total Period (H): ${totalHoursInPeriodMath}\n`
        log += `Disponibilidade: ${availability.toFixed(1)}%\n`
    }

    require('fs').writeFileSync('diagnosis_output.txt', log)
    console.log('Result written to diagnosis_output.txt')
}

main().catch(console.error).finally(() => prisma.$disconnect())

'use server'

import { Perfil } from '@prisma/client'
import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

// --- VEÍCULOS (BASE DE DADOS) ---
import { getSession } from './auth-actions'

export async function getAdminVeiculos() {
    const session = await getSession()
    if (!session) return []

    const where: any = {}
    if (session.perfil !== 'ADMIN') {
        where.unidadeId = session.unidadeId
    }

    const result = await prisma.veiculo.findMany({
        where,
        orderBy: { codigoInterno: 'asc' },
        // @ts-ignore
        include: { unidade: true, documentos: true }
    })

    return JSON.parse(JSON.stringify(result))
}

export async function getAdminUsuarios() {
    const session = await getSession()
    if (!session) return []

    const where: any = {}
    if (session.perfil !== 'ADMIN') {
        where.unidadePadraoId = session.unidadeId
    }

    return await prisma.usuario.findMany({
        where,
        orderBy: { nome: 'asc' },
        include: { empresaPadrao: true, unidadePadrao: true }
    })
}

export async function createUsuario(formData: FormData) {
    try {
        const nome = formData.get('nome') as string
        const email = formData.get('email') as string

        if (!nome || !nome.trim() || !email || !email.trim()) {
            return { success: false, error: 'O Nome e o E-mail são obrigatórios. Por favor, preencha a aba Dados Pessoais.' }
        }

        const senha = formData.get('senha') as string || '123'
        const perfil = formData.get('perfil') as Perfil
        // @ts-ignore
        const area = formData.get('area') || 'GERAL'

        const unidadePadraoId = formData.get('unidadePadraoId') as string
        const session = await getSession()

        let finalUnidadeId = unidadePadraoId !== '' ? unidadePadraoId : null
        // Se não for ADMIN, força a unidade do próprio gestor
        if (session && session.perfil !== 'ADMIN') {
            finalUnidadeId = session.unidadeId
        }

        await prisma.usuario.create({
            data: {
                nome,
                email,
                senha,
                perfil,
                // @ts-ignore
                area: area,
                unidadePadraoId: finalUnidadeId,
                ativo: true
            }
        })
        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (e: any) {
        console.error("ERRO AO CRIAR USUARIO:", e)
        const errorMessage = e?.message || String(e)
        // Check for common Prisma errors: Unique constraint failed
        if (errorMessage.includes('Unique constraint failed')) {
            return { success: false, error: 'Já existe um usuário cadastrado com este e-mail.' }
        }
        return { success: false, error: 'Erro ao criar usuário: ' + errorMessage }
    }
}

// --- EMPRESAS ---
export async function getAdminEmpresas() {
    return await prisma.empresa.findMany({
        include: {
            unidades: true
        }
    })
}

export async function createEmpresa(formData: FormData) {
    try {
        const nomeFantasia = formData.get('nomeFantasia') as string
        const cnpj = formData.get('cnpj') as string

        await prisma.empresa.create({
            data: {
                nomeFantasia,
                razaoSocial: nomeFantasia, // Simplificação
                cnpj
            }
        })
        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao criar empresa' }
    }
}

export async function createUnidade(formData: FormData) {
    try {
        const empresaId = formData.get('empresaId') as string
        const nomeUnidade = formData.get('nomeUnidade') as string
        const cidade = formData.get('cidade') as string
        const estado = formData.get('estado') as string

        await prisma.unidade.create({
            data: {
                empresaId,
                nomeUnidade,
                cidade,
                estado
            }
        })
        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao criar unidade' }
    }
}

// --- SYSTEM PARAMS ---
export async function getSystemParams() {
    const params = await prisma.systemParameters.findMany()

    // Lazy Seed
    if (params.length === 0) {
        const defaults = [
            { key: 'APP_NAME', value: 'Manut Pneus', group: 'GERAL', description: 'Nome da Aplicação' },
            { key: 'MAINTENANCE_MODE', value: 'false', group: 'GERAL', description: 'Modo Manutenção' },
            { key: 'NOTIFY_EMAIL', value: 'admin@eunaman.com', group: 'NOTIFICACAO', description: 'Email para Alertas' },
            { key: 'PREVENTIVA_TOLERANCIA', value: '50', group: 'PCM', description: 'Tolerância (h) para alerta' }
        ]

        for (const d of defaults) {
            await prisma.systemParameters.create({ data: d })
        }
        return await prisma.systemParameters.findMany()
    }

    return params
}

export async function updateSystemParam(formData: FormData) {
    try {
        const key = formData.get('key') as string
        const value = formData.get('value') as string

        await prisma.systemParameters.update({
            where: { key },
            data: { value }
        })
        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao atualizar parâmetro' }
    }
}

export async function toggleUsuarioStatus(id: string, currentStatus: boolean, _formData: FormData) {
    try {
        await prisma.usuario.update({
            where: { id },
            data: { ativo: !currentStatus }
        })
        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao alterar status' }
    }
}

export async function updateUsuario(formData: FormData) {
    try {
        const id = formData.get('id') as string
        const nome = formData.get('nome') as string
        const email = formData.get('email') as string

        if (!nome || !nome.trim() || !email || !email.trim()) {
            return { success: false, error: 'O Nome e o E-mail são obrigatórios.' }
        }

        const perfil = formData.get('perfil') as Perfil
        // @ts-ignore
        const area = formData.get('area')
        const senhaCandidate = formData.get('senha') as string
        const unidadePadraoId = formData.get('unidadePadraoId') as string
        const session = await getSession()

        let finalUnidadeId = unidadePadraoId !== '' ? unidadePadraoId : null

        // Se não for ADMIN, não pode transformar um usuário em "Acesso Global"
        // e sempre força ele para dentro da unidade do gestor
        if (session && session.perfil !== 'ADMIN') {
            finalUnidadeId = session.unidadeId
        }

        const data: any = {
            nome,
            email,
            perfil,
            area,
            unidadePadraoId: finalUnidadeId
        }
        if (senhaCandidate && senhaCandidate.trim() !== '') {
            data.senha = senhaCandidate
        }

        await prisma.usuario.update({
            where: { id },
            data
        })
        revalidatePath('/dashboard/admin')
