export async function importBacklogItems(items: Partial<BacklogItem>[]) {
    try {
        if (items.length === 0) return { success: true, count: 0, duplicates: 0 }

        // Fetch existing items to filter duplicates
        // We select key fields to identify uniqueness
        const existingItems = await prisma.$queryRawUnsafe<any[]>(`
            SELECT os, frota, descricao_atividade, data_evidencia FROM "backlog_pcm"
        `)

        const existingSet = new Set<string>()
        existingItems.forEach((row: any) => {
            // Create signatures. 
            // Priority 1: OS (if present and valid)
            if (row.os && row.os.trim().length > 0) {
                existingSet.add(`os:${row.os.trim().toLowerCase()}`)
            }
            // Priority 2: Composite key (always valid as fallback or secondary check)
            const composite = `comp:${row.frota?.toString().trim().toLowerCase()}|${row.descricao_atividade?.toString().trim().toLowerCase()}|${row.data_evidencia ? new Date(row.data_evidencia).toISOString().split('T')[0] : ''}`
            existingSet.add(composite)
        })

        const uniqueItems = []
        let duplicatesCount = 0

        for (const item of items) {
            let isDuplicate = false

            // Check OS
            if (item.os && item.os.toString().trim().length > 0) {
                if (existingSet.has(`os:${item.os.toString().trim().toLowerCase()}`)) {
                    isDuplicate = true
                }
            }

            // Check Composite if not already found as duplicate by OS
            if (!isDuplicate) {
                const composite = `comp:${item.frota?.toString().trim().toLowerCase()}|${item.descricaoAtividade?.toString().trim().toLowerCase()}|${item.dataEvidencia ? new Date(item.dataEvidencia).toISOString().split('T')[0] : ''}`
                if (existingSet.has(composite)) {
                    isDuplicate = true
                } else {
                    // Add to set so we don't import duplicates properly within the same batch
                    if (item.os && item.os.trim().length > 0) existingSet.add(`os:${item.os.trim().toLowerCase()}`)
                    existingSet.add(composite)
                }
            }

            if (isDuplicate) {
                duplicatesCount++
            } else {
                uniqueItems.push(item)
            }
        }

        if (uniqueItems.length === 0) {
            return { success: true, count: 0, duplicates: duplicatesCount }
        }

        const valuesList: string[] = []

        const fields = [
            'semana', 'mes', 'ano', 'modulo', 'regiao_programacao', 'dias_pendencia_aberta',
            'frota', 'tag', 'tipo', 'descricao_atividade', 'origem', 'criticidade',
            'tempo_execucao_previsto', 'campo_base', 'os', 'material', 'numero_rc',
            'numero_ordem', 'fornecedor', 'detalhamento_pedido', 'tipo_pedido',
            'situacao_rc', 'dias_abertura_req_compras', 'mao_de_obra',
            'delta_evidencia_programacao', 'status_programacao', 'dias_resolucao_pendencia',
            'status', 'observacao', 'unidade'
        ]

        const dateFields = [
            'data_evidencia', 'data_rc', 'data_necessidade_material', 'previsao_material',
            'data_programacao', 'previsao_conclusao_pendencia', 'data_conclusao_pendencia'
        ]

        for (const data of uniqueItems) {
            const values = [
                ...fields.map(f => {
                    let val: any
                    if (f === 'descricao_atividade') val = data.descricaoAtividade
                    else if (f === 'regiao_programacao') val = data.regiaoProgramacao
                    else if (f === 'dias_pendencia_aberta') val = data.diasPendenciaAberta
                    else if (f === 'tempo_execucao_previsto') val = data.tempoExecucaoPrevisto
                    else if (f === 'campo_base') val = data.campoBase
                    else if (f === 'numero_rc') val = data.numeroRc
                    else if (f === 'numero_ordem') val = data.numeroOrdem
                    else if (f === 'detalhamento_pedido') val = data.detalhamentoPedido
                    else if (f === 'tipo_pedido') val = data.tipoPedido
                    else if (f === 'situacao_rc') val = data.situacaoRc
                    else if (f === 'dias_abertura_req_compras') val = data.diasAberturaReqCompras
                    else if (f === 'mao_de_obra') val = data.maoDeObra
                    else if (f === 'delta_evidencia_programacao') val = data.deltaEvidenciaProgramacao
                    else if (f === 'status_programacao') val = data.statusProgramacao
                    else if (f === 'dias_resolucao_pendencia') val = data.diasResolucaoPendencia
                    else if (f === 'unidade') val = data.unidade
                    else val = (data as any)[f]

                    if (val === undefined || val === null || val === '') return 'NULL'
                    if (typeof val === 'string') return `'${val.replace(/'/g, "''")}'`
                    if (val instanceof Date) return `'${val.toISOString()}'`
                    if (typeof val === 'object') return `'${JSON.stringify(val).replace(/'/g, "''")}'`
                    return val
                }),
                ...dateFields.map(f => {
                    let val: any
                    if (f === 'data_evidencia') val = data.dataEvidencia
                    else if (f === 'data_rc') val = data.dataRc
                    else if (f === 'data_necessidade_material') val = data.dataNecessidadeMaterial
                    else if (f === 'previsao_material') val = data.previsaoMaterial
                    else if (f === 'data_programacao') val = data.dataProgramacao
                    else if (f === 'previsao_conclusao_pendencia') val = data.previsaoConclusaoPendencia
                    else if (f === 'data_conclusao_pendencia') val = data.dataConclusaoPendencia

                    if (val === undefined || val === null || val === '') return 'NULL'
                    try {
                        const d = new Date(val)
                        if (isNaN(d.getTime())) return 'NULL'
                        return `'${d.toISOString()}'`
                    } catch {
                        return 'NULL'
                    }
                })
            ].join(', ')

            valuesList.push(`(gen_random_uuid(), NOW(), NOW(), ${values})`)
        }

        const columns = [...fields, ...dateFields].map(f => `"${f}"`).join(', ')

        // Batch insert in chunks of 50
        const CHUNK_SIZE = 50
        for (let i = 0; i < valuesList.length; i += CHUNK_SIZE) {
            const chunk = valuesList.slice(i, i + CHUNK_SIZE)
            const query = `
                INSERT INTO "backlog_pcm" (id, created_at, updated_at, ${columns})
                VALUES ${chunk.join(', ')}
            `
            await prisma.$executeRawUnsafe(query)
        }

        revalidatePath('/dashboard/pcm/backlog')
        return { success: true, count: uniqueItems.length, duplicates: duplicatesCount }
    } catch (e: any) {
        console.error('Import error:', e)
        return { success: false, error: e.message }
    }
}

'use server'

import prisma from '@/lib/prisma'
import { differenceInHours, startOfMonth, endOfMonth, min, max, differenceInMinutes } from 'date-fns'
import { getSession } from './auth-actions'
import { revalidatePath, unstable_noStore as noStore } from 'next/cache'

export interface DashboardFilters {
    dataInicio?: string
    dataFim?: string
    placa?: string
    status?: string
    os?: string
    tipo?: string
}

export async function getDashboardMetrics(filters: DashboardFilters = {}) {
    noStore()
    try {
        const session = await getSession()
        if (!session) return { success: false, error: 'Não autenticado' }

        const now = new Date()

        // Date Range Logic
        let firstDay: Date
        let lastDay: Date

        if (filters.dataInicio) {
            firstDay = new Date(filters.dataInicio)
            // Fix timezone offset issue by treating string as local date or just ensuring hours 00:00
            // Assuming string is YYYY-MM-DD, new Date(str) might be UTC. 
            // Better to use YYYY-MM-DD + 'T00:00:00' to assume local if strict, or just use as is.
            // Let's stick to simple parsing.
            firstDay.setHours(0, 0, 0, 0)
        } else {
            // Default: First day of current month
            firstDay = new Date(now.getFullYear(), now.getMonth(), 1)
        }

        if (filters.dataFim) {
            lastDay = new Date(filters.dataFim)
            lastDay.setHours(23, 59, 59, 999)
        } else {
            // Default: Last day of current month
            lastDay = endOfMonth(now)
        }

        // If the query range ends in the future or includes the current partial month, cap avail calc at 'now'
        const referenceEnd = (lastDay > now) ? now : lastDay

        const unitWhere: any = {}
        if (session.perfil !== 'ADMIN') {
            unitWhere.unidadeId = session.unidadeId
        }

        // --- 1. Filter Construction ---

        // Base vehicle filter (placa/tipo/unidade)
        const veiculoSubWhere: any = { ...unitWhere }
        if (filters.placa) {
            veiculoSubWhere.OR = [
                { placa: { contains: filters.placa, mode: 'insensitive' } },
                { codigoInterno: { contains: filters.placa, mode: 'insensitive' } }
            ]
        }
        if (filters.tipo) {
            veiculoSubWhere.tipoVeiculo = { equals: filters.tipo, mode: 'insensitive' }
        }

        // OS Query
        const osWhere: any = {
            dataAbertura: { lte: lastDay },
            OR: [
                { dataConclusao: null },
                { dataConclusao: { gte: firstDay } }
            ],
            veiculo: veiculoSubWhere
        }
        if (filters.status) osWhere.status = filters.status
        if (filters.os) osWhere.numeroOS = Number(filters.os)

        // Vehicle Query (for Chart/Availability)
        const veiculoWhere: any = {
            ...veiculoSubWhere,
            status: { not: 'DESATIVADO' }
        }

        console.log('[Dashboard] Filtros Recebidos:', filters)
        console.log('[Dashboard] OS Query:', JSON.stringify(osWhere, null, 2))
        console.log('[Dashboard] Veiculo Query:', JSON.stringify(veiculoWhere, null, 2))

        // --- 2. Database Fetching (Parallel) ---
        const [osList, veiculos, docs, preventivePlanos, recentActivity] = await Promise.all([
            prisma.ordemServico.findMany({
                where: osWhere,
                include: { veiculo: true }
            }),
            prisma.veiculo.findMany({
                where: veiculoWhere,
                include: {
                    os: {
                        where: {
                            // OS que abrem antes ou durante o período
                            dataAbertura: { lte: lastDay },
                            // E que fecham DURANTE ou DEPOIS do período (ou ainda estão abertas)
                            OR: [
                                { dataConclusao: null },
                                { dataConclusao: { gte: firstDay } }
                            ],
                            // Inclui TODOS os status que representam veículo indisponível
                            status: { in: ['ABERTA', 'PLANEJADA', 'EM_EXECUCAO', 'CONCLUIDA'] }
                        }
                    }
                }
            }),
            prisma.documentoFrota.findMany({
                where: {
                    veiculo: veiculoWhere,
                    dataValidade: { not: null }
                },
                select: { dataValidade: true }
            }),
            prisma.planoManutencao.findMany({
                where: { veiculo: veiculoWhere },
                include: {
                    veiculo: {
                        select: { placa: true, codigoInterno: true, horimetroAtual: true }
                    }
                }
            }),
            prisma.ordemServico.findMany({
                where: osWhere,
                take: 5,
                orderBy: { dataAbertura: 'desc' },
                include: { veiculo: true }
            })
        ])

        // --- 3. KPI Calculations ---

        const totalOS = osList.length
        const osAbertas = osList.filter(os => ['ABERTA', 'PLANEJADA', 'EM_EXECUCAO'].includes(os.status)).length
        const osFechadas = osList.filter(os => os.status === 'CONCLUIDA').length

        // Availability Math
        const totalHoursInPeriod = Math.max(1, differenceInHours(referenceEnd, firstDay))

        const availabilityData = veiculos.map((v: any) => {
            let totalDowntimeHours = 0

            v.os.forEach((os: any) => {
                // Cálculo de interseção: o tempo que a OS ficou ativa dentro do período de interesse
                const osStart = new Date(os.dataAbertura)
                const osEnd = os.dataConclusao ? new Date(os.dataConclusao) : referenceEnd

                const startCalculo = max([osStart, firstDay])
                const endCalculo = min([osEnd, referenceEnd])

                const minutes = differenceInMinutes(endCalculo, startCalculo)
                if (minutes > 0) totalDowntimeHours += (minutes / 60)
            })

            const totalHoursInPeriodMath = Math.max(1, differenceInMinutes(referenceEnd, firstDay) / 60)
            const availability = Math.max(0, ((totalHoursInPeriodMath - totalDowntimeHours) / totalHoursInPeriodMath) * 100)

            return {
                id: v.id,
                placa: v.placa || v.codigoInterno || 'N/A',
                valor: Number(availability.toFixed(1))
            }
        }).sort((a, b) => a.valor - b.valor)

        const totalAvailability = availabilityData.length > 0
            ? availabilityData.reduce((acc, curr) => acc + curr.valor, 0) / availabilityData.length
            : 100

        // MTTR
        const closedOS = osList.filter(os => os.dataConclusao)
        const totalRepairHours = closedOS.reduce((acc, os) => acc + differenceInHours(new Date(os.dataConclusao!), new Date(os.dataAbertura)), 0)
        const mttr = closedOS.length > 0 ? (totalRepairHours / closedOS.length).toFixed(1) : '0.0'

        // MTBF
        const correctiveOS = osList.filter(os => os.tipoOS === 'CORRETIVA').length
        const totalPossibleHours = totalHoursInPeriod * Math.max(1, veiculos.length)
        const mtbf = correctiveOS > 0 ? (totalPossibleHours / correctiveOS).toFixed(1) : '0.0'


        const today = new Date()
        today.setHours(0, 0, 0, 0)

        const thirtyDaysFromNow = new Date(today)
        thirtyDaysFromNow.setDate(today.getDate() + 30)

        const docStats = docs.reduce((acc, doc) => {
            if (!doc.dataValidade) return acc

            const validade = new Date(doc.dataValidade)
            validade.setHours(0, 0, 0, 0)

            if (validade < today) {
                acc.expired++
            } else if (validade <= thirtyDaysFromNow) {
                acc.attention++
            } else {
                acc.valid++
            }
            return acc
        }, { valid: 0, attention: 0, expired: 0 })


        // Preventive Data Formatting
        const preventiveData = preventivePlanos.map(p => {
            const proximaRevisao = p.ultimoHorimetro + p.intervalo
            const horasRestantes = proximaRevisao - p.veiculo.horimetroAtual

            let fill = '#10B981' // Green
            if (horasRestantes < 0) fill = '#EF4444' // Red
            else if (horasRestantes < 50) fill = '#F59E0B' // Yellow

            return {
                name: `${p.veiculo.placa || p.veiculo.codigoInterno} - ${p.tipo}`,
                value: horasRestantes,
                originalStatus: p.status,
                fill,
                placa: p.veiculo.placa || p.veiculo.codigoInterno
            }
        }).sort((a, b) => a.value - b.value)

        const response = {
            success: true,
            data: {
                kpis: {
                    totalOS,
                    osAbertas,
                    osFechadas,
                    disponibilidadeGlobal: totalAvailability.toFixed(1),
                    mttr,
                    mtbf,
                    docs: docStats
                },
                chartData: availabilityData,
                preventiveData,
                recentActivity
            }
        }

        // Serializar para evitar erros de objeto Date entre Server e Client
        return JSON.parse(JSON.stringify(response))
    } catch (e: any) {
        console.error('[Dashboard Action] Error:', e)
        return { success: false, error: 'Failed to fetch metrics: ' + e.message }
    }
}

'use server'

import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import * as XLSX from 'xlsx'
import { getSession } from './auth-actions'

const docTypes = [
    { prefix: 'laudo', type: 'LAUDO_ELETROMECANICO' },
    { prefix: 'crlv', type: 'CRLV' },
    { prefix: 'implemento', type: 'IMPLEMENTO' },
    { prefix: 'tacografo', type: 'TACOGRAFO' },
    { prefix: 'civ', type: 'CIV_CIPP' }
]

export async function createVeiculo(formData: FormData) {
    const session = await getSession()
    if (!session) return { success: false, error: 'Usuário não autenticado.' }

    const placa = formData.get('placa') as string
    const tipo = formData.get('tipo') as string
    const categoria = formData.get('categoria') as string
    const modulo = formData.get('modulo') as string
    const horimetro = parseInt(formData.get('horimetro') as string) || 0
    const dataAtualizacao = formData.get('dataAtualizacao') as string

    try {
        let unidadeId = session.unidadeId
        let empresaId: string | undefined

        if (!unidadeId) {
            const firstUnit = await prisma.unidade.findFirst()
            if (!firstUnit) return { success: false, error: 'Nenhuma unidade encontrada.' }
            unidadeId = firstUnit.id
            empresaId = firstUnit.empresaId
        } else {
            const unit = await prisma.unidade.findUnique({ where: { id: unidadeId } })
            empresaId = unit?.empresaId
        }

        if (!empresaId) return { success: false, error: 'Empresa não encontrada para esta unidade.' }

        await prisma.$transaction(async (tx: any) => {
            await tx.veiculo.create({
                data: {
                    codigoInterno: placa,
                    placa,
                    tipoVeiculo: typeMap(tipo),
                    categoria,
                    moduloSistema: modulo,
                    horimetroAtual: horimetro,
                    dataAtualizacaoHorimetro: dataAtualizacao ? new Date(dataAtualizacao) : new Date(),
                    fabricante: 'N/A',
                    modelo: 'N/A',
                    ano: new Date().getFullYear(),
                    status: 'DISPONIVEL',
                    empresaId: empresaId!,
                    unidadeId: unidadeId!,
                    kmAtual: 0,
                    documentos: {
                        create: docTypes.map(d => {
                            const num = formData.get(`${d.prefix}_numero`) as string
                            if (!num) return null

                            return {
                                tipo: d.type,
                                numero: num,
                                dataEmissao: formData.get(`${d.prefix}_emissao`) ? new Date(formData.get(`${d.prefix}_emissao`) as string) : null,
                                dataValidade: formData.get(`${d.prefix}_validade`) ? new Date(formData.get(`${d.prefix}_validade`) as string) : null
                            }
                        }).filter(Boolean)
                    }
                }
            })
        })

        revalidatePath('/dashboard/admin')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao criar veículo' }
    }
}

export async function importVeiculosExcel(formData: FormData) {
    console.log('[Import] --- INÍCIO ---')
    try {
        const file = formData.get('file') as File
        if (!file || file.size === 0) return { success: false, error: 'Arquivo não recebido ou vazio.' }

        const arrayBuffer = await file.arrayBuffer()
        const workbook = XLSX.read(new Uint8Array(arrayBuffer), { type: 'array', cellDates: true })
        const worksheet = workbook.Sheets[workbook.SheetNames[0]]
        const data: any[] = XLSX.utils.sheet_to_json(worksheet)

        console.log(`[Import] Linhas lidas: ${data.length}`)
        if (data.length > 0) {
            console.log('[Import] Cabeçalhos encontrados:', Object.keys(data[0]))
        }

        const unidade = await prisma.unidade.findFirst()
        if (!unidade) {
            console.error('[Import] Erro: Sem unidade.')
            return { success: false, error: 'Erro: Nenhuma unidade encontrada no sistema.' }
        }

        let successCount = 0
        let errors = []
        let lastErrorMessage = ''

        if (data.length > 0) {
            console.log('[Import] Cabeçalhos reais do Excel:', Object.keys(data[0]))
        }

        const docConfig = [
            { type: 'LAUDO_ELETROMECANICO', kw: 'laudo' },
            { type: 'CRLV', kw: 'crlv' },
            { type: 'IMPLEMENTO', kw: 'implemento' },
            { type: 'TACOGRAFO', kw: 'tacografo' },
            { type: 'CIV_CIPP', kw: 'civ' }
        ]

        for (const [index, row] of data.entries()) {
            const normalize = (s: any) => s ? s.toString().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim() : "";

            const findCol = (targetKw: string) => {
                const target = normalize(targetKw);
                const key = Object.keys(row).find(k => normalize(k).includes(target));
                if (key) console.log(`[Import] Found column for ${targetKw}: "${key}"`);
                return key ? row[key] : null
            }

            const placaRaw = findCol('placa') || findCol('cod') || findCol('interno') || findCol('veiculo')
            if (!placaRaw) {
                if (index === 0) console.warn('[Import] Falha ao encontrar placa na primeira linha. Chaves:', Object.keys(row));
                console.warn(`[Import] Linha ${index + 1} pulada (sem placa)`)
                continue
            }

            const placa = String(placaRaw).trim()
            console.log(`[Import] Linha ${index + 1} -> Placa: ${placa}`)
            const tipo = String(findCol('tipo') || 'LEVE')
            const categoria = String(findCol('categoria') || 'PROPRIO')
            const modulo = String(findCol('modulo') || 'BASE')
            const horimetro = findCol('horimetro')
            const dataAtu = findCol('atualizacao')

            try {
                // Execute individual elements to track errors better
                const veiculo = await prisma.veiculo.upsert({
                    where: { codigoInterno: placa },
                    update: {
                        tipoVeiculo: typeMap(tipo),
                        // @ts-ignore
                        categoria: categoria,
                        // @ts-ignore
                        moduloSistema: modulo,
                        horimetroAtual: Math.floor(Number(horimetro)) || 0,
                        dataAtualizacaoHorimetro: dataAtu instanceof Date ? dataAtu : (dataAtu ? new Date(dataAtu as any) : null),
                        modelo: String(findCol('modelo') || 'VEICULO')
                    },
                    create: {
                        codigoInterno: placa,
                        placa: placa,
                        tipoVeiculo: typeMap(tipo),
                        // @ts-ignore
                        categoria: categoria,
                        // @ts-ignore
                        moduloSistema: modulo,
                        horimetroAtual: Math.floor(Number(horimetro)) || 0,
                        dataAtualizacaoHorimetro: dataAtu instanceof Date ? dataAtu : (dataAtu ? new Date(dataAtu as any) : null),
                        fabricante: 'GENERICO',
                        modelo: String(findCol('modelo') || 'VEICULO'),
                        ano: new Date().getFullYear(),
                        status: 'DISPONIVEL',
                        empresaId: unidade.empresaId,
                        unidadeId: unidade.id,
                        kmAtual: 0
                    }
                })

                for (const d of docConfig) {
                    const rowKeys = Object.keys(row);
                    const numKey = rowKeys.find(k => normalize(k).includes(d.kw) && (normalize(k).includes('n') || normalize(k).includes('numero')));
                    const emiKey = rowKeys.find(k => normalize(k).includes(d.kw) && (normalize(k).includes('exp') || normalize(k).includes('emissao') || normalize(k).includes('dat')));
                    const valKey = rowKeys.find(k => normalize(k).includes(d.kw) && (normalize(k).includes('val')));

                    if (numKey) {
                        const num = row[numKey];
                        const emissao = emiKey ? row[emiKey] : null;
                        const validade = valKey ? row[valKey] : null;

                        // @ts-ignore
                        await prisma.documentoFrota.upsert({
                            where: { veiculoId_tipo: { veiculoId: veiculo.id, tipo: d.type } },
                            update: {
                                numero: String(num),
                                dataEmissao: emissao instanceof Date ? emissao : (emissao ? new Date(emissao as any) : null),
                                dataValidade: validade instanceof Date ? validade : (validade ? new Date(validade as any) : null)
                            },
                            create: {
                                veiculoId: veiculo.id,
                                tipo: d.type,
                                numero: String(num),
                                dataEmissao: emissao instanceof Date ? emissao : (emissao ? new Date(emissao as any) : null),
                                dataValidade: validade instanceof Date ? validade : (validade ? new Date(validade as any) : null)
                            }
                        })
                    }
                }

                successCount++
                console.log(`[Import] OK: ${placa}`)
            } catch (err: any) {
                console.error(`[Import] Erro no veículo ${placa}:`, err.message)
                errors.push(placa)
                lastErrorMessage = err.message
            }
        }

        revalidatePath('/dashboard/admin')
        return {
            success: true,
            count: successCount,
            errors,
            error: lastErrorMessage // Pass back the last error message for UI debugging
        }
    } catch (e: any) {
        console.error('[Import] Erro Crítico:', e)
        return { success: false, error: 'Erro Crítico: ' + e.message }
    }
}

function getData(val: string) {
    return val ? new Date(val) : null
}

function typeMap(val: string) {
    if (!val) return 'LEVE'
    const v = val.toString().toUpperCase()
    if (v.includes('PESADO') || v.includes('CAMINHAO')) return 'PESADO'
    if (v.includes('MAQUINA')) return 'MAQUINA'
    return 'LEVE'
}

export async function getVehicleDetails(id: string) {
    try {
        const veiculo = await prisma.veiculo.findUnique({
            where: { id },
            include: {
                documentos: {
                    orderBy: { tipo: 'asc' }
                }
            }
        })
        if (!veiculo) return { success: false, error: 'Veículo não encontrado.' }
        const response = { success: true, data: veiculo }
        return JSON.parse(JSON.stringify(response))
    } catch (e: any) {
        return { success: false, error: 'Erro ao buscar veículo: ' + e.message }
    }
}

'use server'

import { getSession } from './auth-actions'
import { TipoOS, StatusOS } from '@prisma/client'
import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'

export async function getOrdensServico(filters: { status?: string, q?: string, tipo?: string } = {}) {
    try {
        const session = await getSession()
        if (!session) return { success: false, error: 'Não autenticado' }

        const where: any = {}

        // Restricted to unit if not admin
        if (session.perfil !== 'ADMIN' && session.perfil !== 'GESTOR' && session.perfil !== 'PCM') {
            where.veiculo = { unidadeId: session.unidadeId }
        }

        // Status Filter
        if (filters.status && filters.status !== 'TODAS') {
            where.status = filters.status
        }

        // Tipo OS Filter
        if (filters.tipo && filters.tipo !== 'TODOS') {
            where.tipoOS = filters.tipo as any
        }

        // Search Query
        if (filters.q) {
            where.OR = [
                { veiculo: { placa: { contains: filters.q, mode: 'insensitive' } } },
                { veiculo: { codigoInterno: { contains: filters.q, mode: 'insensitive' } } },
                { descricao: { contains: filters.q, mode: 'insensitive' } }
            ]
        }

        const os = await prisma.ordemServico.findMany({
            where,
            include: {
                veiculo: true
