export async function createBoletimPneu(data: any) {
  try {
    let veiculoId, dataBoletim, km, observacoes, itens: any[] = []

    if (data instanceof FormData) {
      veiculoId = data.get('veiculoId') as string
      dataBoletim = data.get('data') as string
      km = data.get('km') as string
      observacoes = data.get('observacoes') as string

      const posicoes = [
        'DE', 'DD', 'TEI', 'TEE', 'TDI', 'TDE', 'TEI1', 'TEE1', 'TDI1', 'TDE1', 'ESTEPE'
      ]

      itens = posicoes.map(pos => {
        const sulco = data.get(`sulco_${pos}`)
        if (sulco) {
          return {
            posicao: pos,
            sulcoMm: parseFloat(sulco as string),
            pneuId: null // TODO: Relacionar com pneu real se necessário
          }
        }
        return null
      }).filter(Boolean) as any[]
    } else {
      ({ veiculoId, data: dataBoletim, km, observacoes, itens } = data)
    }

    if (!veiculoId || !dataBoletim) {
      throw new Error('Veículo e Data são obrigatórios')
    }

    const result = await prisma.$transaction(async (tx) => {
      // 1. Criar o boletim
      const boletim = await tx.boletimPneu.create({
        data: {
          veiculoId,
          data: new Date(dataBoletim),
          km: km ? parseInt(km) : 0,
          observacoes,
          itens: {
            create: itens.map((item: any) => ({
              posicao: item.posicao,
              sulcoMm: parseFloat(item.sulcoMm),
              pneuId: item.pneuId || null
            }))
          }
        }
      })

      // 2. Atualizar o sulco_atual_mm de cada pneu (se tiver pneuId)
      for (const item of itens) {
        if (item.pneuId) {
          await tx.pneu.update({
            where: { id: item.pneuId },
            data: {
              sulcoAtualMm: parseFloat(item.sulcoMm)
            }
          })
        }
      }

      return boletim
    })

    revalidatePath('/dashboard/pcm/pneus')
    return { success: true, data: result }
  } catch (error: any) {
    console.error('Error saving boletim:', error)
    return { success: false, error: error.message }
  }
}

'use server'

import { StatusPreventiva } from '@prisma/client'
import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'
import { redirect } from 'next/navigation'
import { getSession } from './auth-actions'

export async function createPreventiva(formData: FormData) {
    const veiculoId = formData.get('veiculoId') as string
    const tipo = formData.get('tipo') as string
    const modulo = formData.get('modulo') as string
    const ultimoHorimetro = Number(formData.get('ultimoHorimetro'))
    const horimetroAtual = Number(formData.get('horimetroAtual'))
    const intervalo = Number(formData.get('intervalo'))
    const dataAtualizacaoStr = formData.get('dataAtualizacao') as string
    let dataAtualizacao = new Date()
    if (dataAtualizacaoStr) {
        const [year, month, day] = dataAtualizacaoStr.split('-').map(Number)
        dataAtualizacao = new Date(year, month - 1, day, 12, 0, 0)
    }
    if (!veiculoId || !tipo || !intervalo) {
        return { success: false, error: 'Campos obrigatórios faltando' }
    }

    try {
        // 1. Atualizar horímetro do veículo se fornecido
        if (horimetroAtual > 0) {
            await prisma.veiculo.update({
                where: { id: veiculoId },
                data: { horimetroAtual }
            })
        }

        // 2. Calcular Status Inicial
        // Se (Ultimo + Intervalo) < Atual -> Atrasado
        let status: StatusPreventiva = 'NO_PRAZO'
        if ((ultimoHorimetro + intervalo) < horimetroAtual) {
            status = 'ATRASADO'
        } else if ((ultimoHorimetro + intervalo) - horimetroAtual < 50) {
            status = 'ATENCAO' // Menos de 50h pra vencer
        }

        // 3. Criar Plano
        await prisma.planoManutencao.create({
            data: {
                veiculoId,
                tipo,
                modulo,
                ultimoHorimetro,
                intervalo,
                dataAtualizacao,
                status: status
            }
        })

        revalidatePath('/dashboard/pcm/preventivas')
        revalidatePath('/dashboard')
        return { success: true }
    } catch (_) {
        return { success: false, error: 'Erro ao salvar dados' }
    }
}

