function Input({ label, value, onChange, placeholder, type = 'text' }: any) {
    let displayValue = value || ''
    if (type === 'date' && value) {
        try {
            if (value instanceof Date) displayValue = value.toISOString().split('T')[0]
            else if (typeof value === 'string' && value.includes('T')) displayValue = value.split('T')[0]
        } catch (e) { }
    }

    return (
        <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-gray-500 ml-1">{label}</label>
            <input
                type={type}
                value={displayValue}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(e.target.value)}
                placeholder={placeholder}
                className="w-full bg-surface border border-border-color rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-primary transition-colors"
            />
        </div>
    )
}

function Select({ label, value, onChange, options }: any) {
    return (
        <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-gray-500 ml-1">{label}</label>
            <select
                value={value || ''}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => onChange(e.target.value)}
                className="w-full bg-surface border border-border-color rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-primary transition-colors"
            >
                <option value="">Selecione...</option>
                {options.map((o: string) => (
                    <option key={o} value={o}>{o}</option>
                ))}
            </select>
        </div>
    )
}

'use client'

import React, { useState } from 'react'
import { X, Upload, FileText, CheckCircle2 } from 'lucide-react'
import * as XLSX from 'xlsx'

interface Props {
    isOpen: boolean
    onClose: () => void
    onSuccess: () => void
}

export default function ImportBacklogDialog({ isOpen, onClose, onSuccess, onImport }: Props & { onImport?: (items: any[]) => Promise<void> }) {
    const [file, setFile] = useState<File | null>(null)
    const [uploading, setUploading] = useState(false)
    const [progress, setProgress] = useState(0)

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0])
        }
    }

    const processExcel = async (file: File) => {
        return new Promise<any[]>((resolve, reject) => {
            const reader = new FileReader()
            reader.onload = (e) => {
                try {
                    const data = new Uint8Array(e.target?.result as ArrayBuffer)
                    const workbook = XLSX.read(data, { type: 'array', cellDates: true })
                    const firstSheetName = workbook.SheetNames[0]
                    const worksheet = workbook.Sheets[firstSheetName]
                    const jsonData = XLSX.utils.sheet_to_json(worksheet, { defval: '' })
                    resolve(jsonData)
                } catch (err) {
                    reject(err)
                }
            }
            reader.onerror = (err) => reject(err)
            reader.readAsArrayBuffer(file)
        })
    }

    const mapDataToBacklogItems = (data: any[]) => {
        // Safe date parse helper to handle string dates from Excel, e.g. "DD/MM/YYYY" or valid Date instances
        const parseDate = (val: any) => {
            if (!val) return undefined;
            if (val instanceof Date) {
                if (!isNaN(val.getTime())) return val;
                return undefined;
            }
            if (typeof val === 'number') {
                const date = new Date(Math.round((val - 25569) * 86400 * 1000));
                if (!isNaN(date.getTime())) return date;
                return undefined;
            }
            if (typeof val === 'string') {
                const parts = val.trim().split(/[\/\-]/);
                if (parts.length === 3) {
                    // Assuming DD/MM/YYYY
                    if (parts[0].length <= 2 && parts[2].length === 4) {
                        const d = new Date(`${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}T12:00:00Z`);
                        if (!isNaN(d.getTime())) return d;
                    }
                    // Assuming YYYY/MM/DD
                    else if (parts[0].length === 4) {
                        const d = new Date(`${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}T12:00:00Z`);
                        if (!isNaN(d.getTime())) return d;
                    }
                }
                const d = new Date(val);
                if (!isNaN(d.getTime())) return d;
            }
            return undefined;
        }

        return data.map(row => {
            // Helper to find key case-insensitively and handle variations
            // We create a map of normalized keys to values for faster lookup
            const normalizedRow: Record<string, any> = {}
            Object.keys(row).forEach(k => {
                const cleanKey = k.toLowerCase().trim()
                    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Remove accents
                    .replace(/[^a-z0-9]/g, "") // Remove special chars
                normalizedRow[cleanKey] = row[k]
            })

            const get = (keyPattern: string) => {
                // keyPattern should be the clean version (lowercase, no accents, no spaces)
                return normalizedRow[keyPattern]
            }

            return {
                semana: get('semana')?.toString(),
                mes: get('mes')?.toString(),
                ano: get('ano')?.toString(),
                dataEvidencia: parseDate(get('dataevidencia') || get('datadaevidencia') || get('data') || get('datadeabertura') || get('dataabertura') || get('dataevidenc')),
                modulo: get('modulo')?.toString(),
                regiaoProgramacao: get('regiaoxprogramacao') || get('regiaoprogramacao'),
                diasPendenciaAberta: Number(get('diaspendencia') || get('diasdependenciaaberta') || 0),
                frota: get('frota')?.toString() || get('placa')?.toString() || get('equipamento')?.toString(),
                tag: get('tag')?.toString(),
                tipo: get('tipo')?.toString(),
                descricaoAtividade: (get('descricao') || get('descricaodaatividade') || get('descricaodoproblema') || get('atividade') || get('sintoma') || get('problema') || get('falha') || get('historico') || get('descricaofalha'))?.toString(),
                origem: get('origem')?.toString(),
                criticidade: get('criticidade')?.toString() || get('grau')?.toString(),
                tempoExecucaoPrevisto: get('tempoexecucao')?.toString() || get('tempodeexecucaoprevisto')?.toString(),
                campoBase: get('campobase')?.toString(),
                os: get('os')?.toString(),
                material: get('material')?.toString(),
                numeroRc: get('nrc')?.toString() || get('numerorc')?.toString() || get('reqcompras')?.toString(),
                numeroOrdem: get('nordem')?.toString() || get('numeroordem')?.toString() || get('npedido')?.toString() || get('numeropedido')?.toString() || get('descrevaasolicitacao')?.toString(),
                fornecedor: get('fornecedor')?.toString(),
                dataRc: parseDate(get('datarc')),
                detalhamentoPedido: get('detalhamento') || get('detalhamentodopedido'),
                dataNecessidadeMaterial: parseDate(get('datanecmaterial') || get('datanecessidadematerial') || get('datanecessidadedomaterial')),
                tipoPedido: get('tipopedido')?.toString(),
                previsaoMaterial: parseDate(get('previsaomaterial') || get('previsaodomaterial')),
                situacaoRc: get('situacaorc')?.toString(),
                diasAberturaReqCompras: Number(get('diasabertura') || get('diasaberturapendenciareqcompras') || 0),
                dataProgramacao: parseDate(get('dataprogramacao') || get('datadeprogramacao')),
                maoDeObra: get('maodeobra')?.toString(),
                deltaEvidenciaProgramacao: Number(get('delta') || get('deltaevidenciavsdataprogramacao') || get('deltaevidencia') || 0),
                statusProgramacao: get('statusprogramacao') || get('situacaoprogramacao'),
                previsaoConclusaoPendencia: parseDate(get('previsaoconclusao') || get('previsaodeconclusaopendencia')),
                dataConclusaoPendencia: parseDate(get('dataconclusao') || get('dataconclusaodapendencia')),
                diasResolucaoPendencia: Number(get('diasresolucao') || get('diasderesolucaodapendencia') || 0),
                status: get('status')?.toString(),
                unidade: get('unidade')?.toString() || get('projeto')?.toString(),
                observacao: get('observacao') || get('obeservacao')
            }
        })
    }

    const handleImport = async () => {
        if (!file) return
        setUploading(true)

        try {
            // Emulate progress
            const interval = setInterval(() => {
                setProgress(prev => {
                    if (prev >= 90) {
                        clearInterval(interval)
                        return 90
                    }
                    return prev + 10
                })
            }, 100)

            let items: any[] = []
            if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
                const rawData = await processExcel(file)
                items = mapDataToBacklogItems(rawData)
            } else {
                // PDF import not supported yet
                alert('Importação de PDF requer processamento específico. Por favor use Excel.')
                setUploading(false)
                clearInterval(interval)
                return
            }

            clearInterval(interval)
            setProgress(100)

            if (onImport) {
                await onImport(items)
            } else {
                // Fallback for simulation
                await new Promise(r => setTimeout(r, 500))
            }

            setUploading(false)
            onSuccess()
            onClose()

        } catch (error) {
            console.error(error)
            alert('Erro ao processar arquivo.')
            setUploading(false)
            setProgress(0)
        }
    }

    if (!isOpen) return null

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-surface border border-border-color w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                <div className="p-4 border-b border-border-color flex justify-between items-center bg-surface-highlight/10">
                    <h3 className="text-lg font-black tracking-tight text-foreground flex items-center gap-2">
                        Importar Backlog
                    </h3>
                    <button onClick={onClose} className="text-gray-500 hover:text-red-500 transition-colors">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <div className="p-8 flex flex-col items-center justify-center text-center space-y-4">
                    <div className={`w-20 h-20 rounded-full flex items-center justify-center ${file ? 'bg-green-500/10 text-green-500' : 'bg-primary/10 text-primary'} transition-colors`}>
                        {file ? <CheckCircle2 className="w-10 h-10" /> : <Upload className="w-10 h-10" />}
                    </div>

                    <div className="space-y-2">
                        <h4 className="text-sm font-bold text-foreground">
                            {file ? file.name : 'Selecione o arquivo Excel'}
                        </h4>
                        <p className="text-xs text-gray-500 max-w-[200px] mx-auto">
                            Arraste e solte ou clique para selecionar o arquivo de backlog (.xlsx) para importação.
                        </p>
                    </div>

                    <input
                        type="file"
                        accept=".xlsx,.xls"
                        onChange={handleFileChange}
                        className="hidden"
                        id="file-upload"
                    />

                    {!file && (
                        <label
                            htmlFor="file-upload"
                            className="px-6 py-2 bg-surface text-foreground border border-border-color hover:bg-surface-highlight rounded-xl text-xs font-black uppercase tracking-widest cursor-pointer transition-all"
                        >
                            Escolher Arquivo
                        </label>
                    )}

                    {uploading && (
                        <div className="w-full space-y-1">
                            <div className="flex justify-between text-[10px] font-black uppercase text-gray-500">
                                <span>Processando...</span>
                                <span>{progress}%</span>
                            </div>
                            <div className="w-full h-1 bg-gray-200 rounded-full overflow-hidden">
                                <div className="h-full bg-primary transition-all duration-200" style={{ width: `${progress}%` }} />
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-4 border-t border-border-color flex justify-end gap-2 bg-surface-highlight/5">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-xs font-black uppercase tracking-widest text-gray-500 hover:text-foreground hover:bg-surface-highlight rounded-lg transition-colors"
                    >
                        Cancelar
                    </button>
                    <button
                        onClick={handleImport}
                        disabled={!file || uploading}
                        className="px-6 py-2 text-xs font-black uppercase tracking-widest bg-primary text-white rounded-lg shadow-lg shadow-primary/20 hover:bg-primary/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        Importar Dados
                    </button>
                </div>
            </div>
        </div>
    )
}

'use client'

import { useState, useEffect } from 'react'
import { CheckCircle2, XCircle, MinusCircle, ChevronDown, ChevronUp, ArrowLeft, Send, Truck, User, Calendar, Clock, Camera, X, ImagePlus, LogIn, LogOut } from 'lucide-react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { saveChecklist } from '@/app/actions/pcm-actions'

type StatusType = 'OK' | 'NC' | 'NA' | null

interface ChecklistItem {
    id: string
    texto: string
    categoria: string | null
    obrigatorio: boolean
    ordem: number
}

interface Formulario {
    id: string
    nome: string
    descricao: string | null
}

interface Veiculo {
    id: string
    codigoInterno: string
    placa: string | null
    modelo: string
}

interface Props {
    formulario: Formulario
    grouped: Record<string, ChecklistItem[]>
    tipoLabel: string
    veiculos: Veiculo[]
    usuarioNome: string
}

const STATUS_CONFIG = {
    OK: { label: 'Conforme', color: 'bg-emerald-500 text-white ring-emerald-500', icon: CheckCircle2, textColor: 'text-emerald-600' },
    NC: { label: 'Não Conforme', color: 'bg-red-500 text-white ring-red-500', icon: XCircle, textColor: 'text-red-600' },
    NA: { label: 'N/A', color: 'bg-gray-400 text-white ring-gray-400', icon: MinusCircle, textColor: 'text-gray-500' },
}

// Pneu positions extracted from item text
// Pneu positions requested by user
const PNEU_POSITIONS = ['DE', 'DD', 'TEI', 'TEE', 'TDI', 'TDE', 'TEI1', 'TEE1', 'TDI1', 'TDE1', 'ESTEPE']

export default function ChecklistForm({ formulario, grouped, tipoLabel, veiculos, usuarioNome }: Props) {
    const pathname = usePathname()
    const isStandalone = pathname?.startsWith('/checklist-app')
    const backPath = isStandalone ? '/checklist-app' : '/dashboard/pcm/checklist'
    const selectionPath = isStandalone ? '/checklist-app/novo' : '/dashboard/pcm/checklist/novo'

    const [respostas, setRespostas] = useState<Record<string, StatusType>>({})
    const [veiculoId, setVeiculoId] = useState('')
    const [responsavel, setResponsavel] = useState(usuarioNome)
    const [dataHora, setDataHora] = useState(() => {
        const now = new Date()
        return {
            data: now.toISOString().slice(0, 10),
            hora: now.toTimeString().slice(0, 5)
        }
    })
    const [observacoes, setObservacoes] = useState<Record<string, string>>({})
    const [fotos, setFotos] = useState<Record<string, string[]>>({})
    const [collapsed, setCollapsed] = useState<Record<string, boolean>>({})
    const [obsGerais, setObsGerais] = useState('')
    const [submitted, setSubmitted] = useState(false)
    const [loading, setLoading] = useState(false)
    const [pneuNumeros, setPneuNumeros] = useState<Record<string, string>>({})
    const [tipo, setTipo] = useState<'ENTRADA' | 'SAIDA'>('ENTRADA')

    const allItems = Object.values(grouped).flat()
    const totalItems = allItems.length
    const answered = allItems.filter(i => respostas[i.id] !== null && respostas[i.id] !== undefined).length
    const ncCount = allItems.filter(i => respostas[i.id] === 'NC').length
    const progress = Math.round((answered / totalItems) * 100)

    const setStatus = (itemId: string, status: StatusType) => {
        setRespostas(p => ({ ...p, [itemId]: p[itemId] === status ? null : status }))
    }

    const addFoto = (itemId: string, file: File) => {
        const current = fotos[itemId] || []
        if (current.length >= 4) return
        const reader = new FileReader()
        reader.onload = (e) => {
            const base64 = e.target?.result as string
            setFotos(p => ({ ...p, [itemId]: [...(p[itemId] || []), base64] }))
        }
        reader.readAsDataURL(file)
    }

    const removeFoto = (itemId: string, idx: number) => {
        setFotos(p => ({ ...p, [itemId]: (p[itemId] || []).filter((_, i) => i !== idx) }))
    }

    const toggleCollapse = (cat: string) => {
        setCollapsed(p => ({ ...p, [cat]: !p[cat] }))
    }

    const handleSubmit = async () => {
        if (!veiculoId) {
            alert('Por favor, selecione o veículo/placa.')
            return
        }
        if (!responsavel.trim()) {
            alert('Por favor, informe o nome do responsável.')
            return
        }
        const unanswered = allItems.filter(i => !respostas[i.id] && i.obrigatorio)
        if (unanswered.length > 0) {
            alert(`Por favor, responda todos os itens obrigatórios. Faltam ${unanswered.length} item(ns).`)
            return
        }
        setLoading(true)
        try {
            const dataResposta = new Date(`${dataHora.data}T${dataHora.hora}`)

            const payload = {
                formularioId: formulario.id,
                veiculoId: veiculoId,
                tipo: tipo,
                dataResposta,
                observacoesGerais: obsGerais,
                respostas: allItems.map(item => ({
                    itemId: item.id,
                    status: respostas[item.id] || 'OK',
                    observacao: observacoes[item.id] || undefined
                }))
            }

            const result = await saveChecklist(payload)

            if (result.success) {
                setSubmitted(true)
            } else {
                alert(result.error || 'Erro ao salvar checklist.')
            }
        } catch (error) {
            console.error('Submit error:', error)
            alert('Falha ao enviar checklist. Verifique sua conexão.')
        } finally {
            setLoading(false)
        }
    }

    if (submitted) {
        return (
            <div className="max-w-xl mx-auto text-center py-20 animate-in fade-in duration-500">
                <div className="w-24 h-24 rounded-full bg-emerald-50 border-4 border-emerald-200 flex items-center justify-center mx-auto mb-6">
                    <CheckCircle2 className="w-12 h-12 text-emerald-500" />
                </div>
                <h2 className="text-2xl font-black text-foreground mb-2">Checklist Enviado!</h2>
                <p className="text-gray-500 font-medium mb-2">
                    {answered} itens respondidos · <span className="text-red-500 font-bold">{ncCount} não conformes</span>
                </p>
                <p className="text-sm text-gray-400 mb-8">O checklist foi registrado com sucesso.</p>
                <Link href={backPath} className="inline-flex items-center gap-2 bg-primary text-white px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-emerald-600 transition-all">
                    <ArrowLeft className="w-4 h-4" />
                    Voltar ao Checklist
                </Link>
            </div>
        )
    }

    return (
        <div className="max-w-2xl mx-auto space-y-6 animate-in fade-in duration-300">
            {/* Header */}
            <div className="flex items-center gap-4">
                <Link href={selectionPath} className="w-10 h-10 rounded-xl bg-surface-highlight border border-border-color flex items-center justify-center hover:border-primary/40 transition-all">
                    <ArrowLeft className="w-4 h-4 text-foreground" />
                </Link>
                <div className="flex-1">
                    <h1 className="text-2xl font-black text-foreground tracking-tight">{formulario.nome}</h1>
                    <p className="text-sm text-gray-500 font-medium">{totalItems} itens de verificação</p>
                </div>
                <div className="text-right">
                    <div className="text-2xl font-black text-primary">{progress}%</div>
                    <div className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{answered}/{totalItems}</div>
                </div>
            </div>

            {/* Identification Card */}
            <div className="dashboard-card p-4 sm:p-5 space-y-4">
                <h3 className="font-black text-[10px] text-gray-400 uppercase tracking-widest">Identificação</h3>
                <div className="grid grid-cols-2 gap-3 sm:gap-4">
                    {/* Placa / Veículo */}
                    <div className="col-span-2 space-y-1.5">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1.5"><Truck className="w-3 h-3" /> Placa / Equipamento *</label>
                        <select
                            value={veiculoId}
                            onChange={e => setVeiculoId(e.target.value)}
                            required
                            className="w-full bg-surface-highlight border border-border-color rounded-xl px-3 py-2.5 text-sm font-semibold text-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all"
                        >
                            <option value="">Selecione...</option>
                            {veiculos.map(v => (
                                <option key={v.id} value={v.id}>
                                    {v.codigoInterno} {v.placa ? `(${v.placa})` : ''}
                                </option>
                            ))}
                        </select>
                    </div>

                    {/* Data */}
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1.5"><Calendar className="w-3 h-3" /> Data *</label>
                        <input
                            type="date"
                            value={dataHora.data}
                            onChange={e => setDataHora(p => ({ ...p, data: e.target.value }))}
                            className="w-full bg-surface-highlight border border-border-color rounded-xl px-3 py-2.5 text-sm font-semibold text-foreground focus:outline-none"
                        />
                    </div>

                    {/* Hora */}
                    <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1.5"><Clock className="w-3 h-3" /> Hora *</label>
                        <input
                            type="time"
                            value={dataHora.hora}
                            onChange={e => setDataHora(p => ({ ...p, hora: e.target.value }))}
                            className="w-full bg-surface-highlight border border-border-color rounded-xl px-3 py-2.5 text-sm font-semibold text-foreground focus:outline-none"
                        />
                    </div>

                    {/* Responsável */}
                    <div className="col-span-2 space-y-1.5">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1.5"><User className="w-3 h-3" /> Responsável *</label>
                        <input
                            type="text"
                            value={responsavel}
                            onChange={e => setResponsavel(e.target.value)}
                            placeholder="Nome do operador"
                            className="w-full bg-surface-highlight border border-border-color rounded-xl px-3 py-2.5 text-sm font-semibold text-foreground placeholder-gray-400 focus:outline-none"
                        />
                    </div>

                    {/* Tipo de Checklist (Entrada/Saída) */}
                    <div className="sm:col-span-2 space-y-1.5 pt-2">
                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center gap-1.5">Identificação do Fluxo *</label>
                        <div className="grid grid-cols-2 gap-3">
                            <button
                                type="button"
                                onClick={() => setTipo('ENTRADA')}
                                className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 transition-all font-bold text-sm ${tipo === 'ENTRADA'
                                    ? 'bg-primary/5 border-primary text-primary shadow-sm'
                                    : 'bg-surface-highlight border-border-color text-gray-400 hover:border-gray-300'
                                    }`}
                            >
                                <LogIn className="w-4 h-4" />
                                Entrada
                            </button>
                            <button
                                type="button"
                                onClick={() => setTipo('SAIDA')}
                                className={`flex items-center justify-center gap-2 py-3 rounded-xl border-2 transition-all font-bold text-sm ${tipo === 'SAIDA'
                                    ? 'bg-amber-500/5 border-amber-500 text-amber-600 shadow-sm'
                                    : 'bg-surface-highlight border-border-color text-gray-400 hover:border-gray-300'
                                    }`}
                            >
                                <LogOut className="w-4 h-4" />
                                Saída
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Progress bar */}
            <div className="w-full h-2 bg-surface-highlight rounded-full overflow-hidden border border-border-color/50">
                <div
                    className="h-full bg-primary rounded-full transition-all duration-500"
                    style={{ width: `${progress}%` }}
                />
            </div>

            {/* Stats */}
            {answered > 0 && (
                <div className="grid grid-cols-3 gap-3">
                    <div className="dashboard-card p-4 text-center">
                        <div className="text-xl font-black text-emerald-500">{allItems.filter(i => respostas[i.id] === 'OK').length}</div>
                        <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Conformes</div>
                    </div>
                    <div className="dashboard-card p-4 text-center">
                        <div className="text-xl font-black text-red-500">{ncCount}</div>
                        <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Não Conformes</div>
                    </div>
                    <div className="dashboard-card p-4 text-center">
                        <div className="text-xl font-black text-gray-400">{allItems.filter(i => respostas[i.id] === 'NA').length}</div>
                        <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">N/A</div>
                    </div>
                </div>
            )}

            {/* Checklist Categories */}
            {Object.entries(grouped).map(([categoria, items]) => (
                <div key={categoria} className="dashboard-card overflow-hidden">
                    {/* Category Header */}
                    <button
                        onClick={() => toggleCollapse(categoria)}
                        className="w-full flex items-center justify-between p-5 text-left hover:bg-surface-highlight/50 transition-colors"
                    >
                        <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full bg-primary" />
                            <span className="font-black text-sm text-foreground uppercase tracking-widest">{categoria}</span>
                            <span className="text-[10px] font-bold text-gray-400 bg-surface-highlight px-2 py-0.5 rounded-full border border-border-color/50">
                                {items.filter(i => respostas[i.id]).length}/{items.length}
                            </span>
                        </div>
                        {collapsed[categoria] ? <ChevronDown className="w-4 h-4 text-gray-400" /> : <ChevronUp className="w-4 h-4 text-gray-400" />}
                    </button>

                    {/* PNEUS: special number inputs before items */}
                    {!collapsed[categoria] && categoria.toLowerCase().includes('pneu') && (
                        <div className="border-t border-border-color/50 px-5 py-4 bg-surface-highlight/30">
                            <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-3">Identificação dos Pneus (Nº de Série)</p>
                            <div className="grid grid-cols-2 gap-3">
                                {PNEU_POSITIONS.map(pos => (
                                    <div key={pos} className={`${pos === 'ESTEPE' ? 'col-span-2' : ''} space-y-1`}>
                                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-wider">{pos}</label>
                                        <input
                                            type="text"
                                            placeholder="Nº do pneu"
                                            value={pneuNumeros[pos] || ''}
                                            onChange={e => setPneuNumeros(p => ({ ...p, [pos]: e.target.value }))}
                                            className="w-full bg-white dark:bg-surface border border-border-color rounded-lg px-3 py-2 text-sm font-semibold text-foreground placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all"
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Items */}
                    {!collapsed[categoria] && (
                        <div className="divide-y divide-border-color/50 border-t border-border-color/50">
                            {items.map((item, idx) => {
                                const status = respostas[item.id]
                                const isNC = status === 'NC'
                                return (
                                    <div key={item.id} className={`px-5 py-4 transition-colors ${isNC ? 'bg-red-50/30 dark:bg-red-950/10' : ''}`}>
                                        <div className="flex items-start gap-4">
                                            {/* Item number */}
                                            <div className="w-7 h-7 rounded-lg bg-surface-highlight border border-border-color flex items-center justify-center shrink-0 mt-0.5">
                                                <span className="text-[10px] font-black text-gray-500">{idx + 1}</span>
                                            </div>

                                            {/* Item text */}
                                            <div className="flex-1 min-w-0">
                                                <p className="text-sm font-semibold text-foreground leading-snug">
                                                    {item.texto}
                                                    {item.obrigatorio && <span className="text-red-400 ml-1 text-xs">*</span>}
                                                </p>

                                                {/* Status buttons */}
                                                <div className="flex gap-2 mt-3 flex-wrap">
                                                    {(['OK', 'NC', 'NA'] as StatusType[]).map(s => {
                                                        const cfg = STATUS_CONFIG[s!]
                                                        const Icon = cfg.icon
                                                        const isSelected = status === s
                                                        return (
                                                            <button
                                                                key={s}
                                                                onClick={() => setStatus(item.id, s)}
                                                                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ring-2 ${isSelected
                                                                    ? `${cfg.color} ring-opacity-50 scale-105 shadow-lg`
                                                                    : 'bg-surface-highlight text-gray-500 ring-transparent hover:ring-1 hover:ring-border-color'
                                                                    }`}
                                                            >
                                                                <Icon className="w-3.5 h-3.5" />
                                                                {cfg.label}
                                                            </button>
                                                        )
                                                    })}
                                                </div>

                                                {/* NC: Observation + Photos */}
                                                {isNC && (
                                                    <div className="mt-3 space-y-3">
                                                        <textarea
                                                            value={observacoes[item.id] || ''}
                                                            onChange={e => setObservacoes(p => ({ ...p, [item.id]: e.target.value }))}
                                                            placeholder="Descreva o problema encontrado..."
                                                            rows={2}
                                                            className="w-full text-sm bg-white dark:bg-surface border border-red-200 dark:border-red-900/30 rounded-xl px-3 py-2 text-foreground placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-red-300 dark:focus:ring-red-800 resize-none"
                                                        />

                                                        {/* Photo upload section */}
                                                        <div className="space-y-2">
                                                            <div className="flex items-center justify-between">
                                                                <span className="text-[10px] font-black text-red-400 uppercase tracking-widest flex items-center gap-1">
                                                                    <Camera className="w-3 h-3" /> Fotos ({(fotos[item.id] || []).length}/4)
                                                                </span>
                                                                {(fotos[item.id] || []).length < 4 && (
                                                                    <label className="cursor-pointer flex items-center gap-1.5 text-[11px] font-black text-red-500 hover:text-red-700 transition-colors">
                                                                        <ImagePlus className="w-4 h-4" />
                                                                        Adicionar foto
                                                                        <input
                                                                            type="file"
                                                                            accept="image/*"
                                                                            capture="environment"
                                                                            className="hidden"
                                                                            onChange={e => {
                                                                                const file = e.target.files?.[0]
                                                                                if (file) addFoto(item.id, file)
                                                                                e.target.value = ''
                                                                            }}
                                                                        />
                                                                    </label>
                                                                )}
                                                            </div>

                                                            {/* Thumbnails */}
                                                            {(fotos[item.id] || []).length > 0 && (
                                                                <div className="flex gap-2 flex-wrap">
                                                                    {(fotos[item.id] || []).map((src, photoIdx) => (
                                                                        <div key={photoIdx} className="relative w-20 h-20 rounded-xl overflow-hidden border-2 border-red-200 dark:border-red-900/40 shadow-md group/photo">
                                                                            <img src={src} alt={`foto-${photoIdx + 1}`} className="w-full h-full object-cover" />
                                                                            <button
                                                                                onClick={() => removeFoto(item.id, photoIdx)}
                                                                                className="absolute top-1 right-1 w-5 h-5 bg-red-600 rounded-full flex items-center justify-center opacity-0 group-hover/photo:opacity-100 transition-opacity shadow-lg"
                                                                            >
                                                                                <X className="w-3 h-3 text-white stroke-[3px]" />
                                                                            </button>
                                                                        </div>
                                                                    ))}
                                                                </div>
                                                            )}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </div>
            ))}

            {/* Observações Gerais */}
            <div className="dashboard-card p-5 space-y-3">
                <h3 className="font-black text-sm text-foreground uppercase tracking-widest">Observações Gerais</h3>
                <textarea
                    value={obsGerais}
                    onChange={e => setObsGerais(e.target.value)}
                    placeholder="Observações adicionais do executante do checklist..."
                    rows={3}
                    className="w-full text-sm bg-surface-highlight border border-border-color rounded-xl px-4 py-3 text-foreground placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary/20 resize-none"
                />
            </div>

            {/* Submit */}
            <button
                onClick={handleSubmit}
                disabled={loading || answered === 0}
                className="w-full flex items-center justify-center gap-3 bg-primary hover:bg-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed text-white py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-xl shadow-primary/20 active:scale-95"
            >
                <Send className="w-4 h-4" />
                {loading ? 'Enviando...' : `Finalizar Checklist (${answered}/${totalItems})`}
            </button>

            <p className="text-center text-[11px] text-gray-400 font-medium pb-8">
                * Itens obrigatórios devem ser respondidos antes de finalizar
            </p>
        </div>
    )
}

import prisma from '@/lib/prisma'
import { notFound } from 'next/navigation'
import { getSession } from '@/app/actions/auth-actions'
import ChecklistForm from './ChecklistForm'

export default async function PreencherChecklistPage(props: any) {
    const { tipo } = await props.searchParams
    const session = await getSession()

    // Fetch form matching the tipo (nome exato passado na URL)
    const formulario = await prisma.checklistFormulario.findFirst({
        where: {
            nome: { equals: tipo, mode: 'insensitive' },
            ativo: true
        },
        include: {
            itens: {
                orderBy: { ordem: 'asc' }
            }
        }
    })

    if (!formulario) return notFound()

    // Group items by categoria
    const grouped = formulario.itens.reduce((acc: Record<string, typeof formulario.itens>, item) => {
        const cat = item.categoria || 'Geral'
        if (!acc[cat]) acc[cat] = []
        acc[cat].push(item)
        return acc
    }, {})

    // Fetch all active vehicles for the plate selector
    const veiculos = await prisma.veiculo.findMany({
        where: { status: { not: 'DESATIVADO' } },
        select: { id: true, codigoInterno: true, placa: true, modelo: true },
        orderBy: { codigoInterno: 'asc' }
    })

    const serializedForm = JSON.parse(JSON.stringify(formulario))
    const serializedVeiculos = JSON.parse(JSON.stringify(veiculos))

    return (
        <ChecklistForm
            formulario={serializedForm}
            grouped={grouped}
            tipoLabel={tipo}
            veiculos={serializedVeiculos}
            usuarioNome={session?.nome || ''}
        />
    )
}

'use client'

import { useState } from 'react'
import { Upload, X, FileSpreadsheet, Check, AlertCircle, Loader2 } from 'lucide-react'
import * as XLSX from 'xlsx'
import { importOrdensServico } from '@/app/actions/pcm-actions'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'

export default function ImportOsDialog({ open, onOpenChange }: { open: boolean, onOpenChange: (open: boolean) => void }) {
    const [file, setFile] = useState<File | null>(null)
    const [loading, setLoading] = useState(false)
    const [result, setResult] = useState<{ success: boolean, count?: number, errors?: number, message?: string, error?: string } | null>(null)

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0]
        if (selectedFile) {
            setFile(selectedFile)
            setResult(null)
        }
    }

    const handleImport = async () => {
        if (!file) return

        setLoading(true)
        try {
            const reader = new FileReader()
            reader.onload = async (e) => {
                const data = new Uint8Array(e.target?.result as ArrayBuffer)
                const workbook = XLSX.read(data, { type: 'array' })
                const sheetName = workbook.SheetNames[0]
                const worksheet = workbook.Sheets[sheetName]
                const jsonData = XLSX.utils.sheet_to_json(worksheet)

                console.log('Importing data:', jsonData)
                const res = await importOrdensServico(jsonData)
                setResult(res)
                if (res.success) {
                    setFile(null)
                }
            }
            reader.readAsArrayBuffer(file)
        } catch (error) {
            console.error('Import error:', error)
            setResult({ success: false, message: 'Erro ao processar o arquivo.' })
        } finally {
            setLoading(false)
        }
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md">
                <DialogHeader>
                    <DialogTitle className="text-xl font-black flex items-center gap-2">
                        <FileSpreadsheet className="w-6 h-6 text-primary" />
                        Importar O.S. (Excel)
                    </DialogTitle>
                    <DialogDescription className="font-medium text-gray-500">
                        Selecione um arquivo Excel (.xlsx ou .xls) com as colunas:
                        <span className="block mt-1 font-bold text-foreground">placa, codigoInterno, tipo, status, descricao, dataAbertura</span>
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-6 pt-4">
                    {!result?.success && (
                        <div className="relative group">
                            <input
                                type="file"
                                accept=".xlsx, .xls"
                                onChange={handleFileChange}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                            />
                            <div className={`border-2 border-dashed rounded-2xl p-8 text-center transition-all ${file ? 'border-primary/50 bg-primary/5' : 'border-border-color hover:border-primary/30 bg-surface-highlight/30'}`}>
                                <Upload className={`w-10 h-10 mx-auto mb-3 ${file ? 'text-primary' : 'text-gray-400'}`} />
                                <p className="text-sm font-black text-foreground">
                                    {file ? file.name : 'Clique ou arraste o arquivo aqui'}
                                </p>
                                <p className="text-[10px] font-bold text-gray-400 uppercase mt-1">Excel (.xlsx ou .xls)</p>
                            </div>
                        </div>
                    )}

                    {result && (
                        <div className={`p-4 rounded-xl flex items-start gap-3 ${result.success ? 'bg-emerald-500/10 text-emerald-600 border border-emerald-500/20' : 'bg-red-500/10 text-red-600 border border-red-500/20'}`}>
                            {result.success ? <Check className="w-5 h-5 shrink-0" /> : <AlertCircle className="w-5 h-5 shrink-0" />}
                            <div>
                                <h4 className="text-sm font-black uppercase tracking-tight">{result.success ? 'Importação Concluída!' : 'Erro na Importação'}</h4>
                                {result.success ? (
                                    <p className="text-xs font-bold mt-1">
                                        {result.count} O.S. importadas com sucesso. {result.errors ? `(${result.errors} falhas)` : ''}
                                    </p>
                                ) : (
                                    <p className="text-xs font-bold mt-1">{result.message || result.error}</p>
                                )}
                            </div>
                        </div>
                    )}

                    <div className="flex gap-3">
                        <button
                            onClick={() => onOpenChange(false)}
                            className="flex-1 px-6 py-3 rounded-2xl bg-surface-highlight border border-border-color text-foreground font-black text-xs uppercase tracking-widest hover:border-gray-400 transition-all"
                        >
                            Fechar
                        </button>
                        {!result?.success && (
                            <button
                                onClick={handleImport}
                                disabled={!file || loading}
                                className="flex-[2] px-6 py-3 rounded-2xl bg-primary text-white font-black text-xs uppercase tracking-widest hover:bg-orange-600 transition-all shadow-lg shadow-primary/20 disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
                                Iniciar Importação
                            </button>
                        )}
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    )
}

'use client'

import { Search, Filter, Calendar, X, Check } from 'lucide-react'
import { useRouter, useSearchParams } from 'next/navigation'
import { useState, useEffect, useCallback } from 'react'
import SearchInput from './SearchInput'

export default function OsFilters() {
    const router = useRouter()
    const searchParams = useSearchParams()

    // Get current values from URL
    const currentStatus = searchParams.get('status') || ''
    const currentTipo = searchParams.get('tipo') || ''
    const searchQuery = searchParams.get('q') || ''

    const updateFilters = useCallback((updates: Record<string, string | null>) => {
        const params = new URLSearchParams(searchParams.toString())

        Object.entries(updates).forEach(([key, value]) => {
            if (value === null || value === '') {
                params.delete(key)
            } else {
                params.set(key, value)
            }
        })

        router.push(`/dashboard/pcm/os?${params.toString()}`)
    }, [router, searchParams])

    const clearFilters = () => {
        router.push('/dashboard/pcm/os')
    }

    const hasFilters = currentStatus || currentTipo || searchQuery

    return (
        <div className="flex flex-col lg:flex-row items-stretch lg:items-center gap-2 w-full p-2">
            {/* Search Input */}
            <div className="flex-1 min-w-[300px]">
                <SearchInput defaultValue={searchQuery} />
            </div>

            {/* Quick Filters */}
            <div className="flex items-center gap-2 overflow-x-auto pb-2 lg:pb-0 scrollbar-hide no-scrollbar">
                {/* Status Selector */}
                <select 
                    value={currentStatus}
                    onChange={(e) => updateFilters({ status: e.target.value })}
                    className="bg-surface border border-border-color rounded-2xl px-4 py-3.5 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-primary hover:border-primary/30 transition-all outline-none cursor-pointer appearance-none min-w-[140px]"
                >
                    <option value="">Todos Status</option>
                    <option value="ABERTA">Aberta</option>
                    <option value="PLANEJADA">Planejada</option>
                    <option value="EM_EXECUCAO">Em Execução</option>
                    <option value="CONCLUIDA">Concluída</option>
                    <option value="CANCELADA">Cancelada</option>
                </select>

                {/* Type Selector */}
                <select 
                    value={currentTipo}
                    onChange={(e) => updateFilters({ tipo: e.target.value })}
                    className="bg-surface border border-border-color rounded-2xl px-4 py-3.5 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-primary hover:border-primary/30 transition-all outline-none cursor-pointer appearance-none min-w-[160px]"
                >
                    <option value="">Todos Tipos</option>
                    <option value="PREVENTIVA">Preventiva</option>
                    <option value="CORRETIVA">Corretiva</option>
                    <option value="INSPECAO">Inspeção</option>
                    <option value="MELHORIA">Melhoria</option>
                </select>

                {/* Clear Filters Button */}
                {hasFilters && (
                    <button 
                        onClick={clearFilters}
                        className="flex items-center gap-2 px-6 py-3.5 rounded-2xl bg-red-500/10 text-red-500 hover:bg-red-500/20 border border-red-500/20 transition-all active:scale-95 text-[10px] font-black uppercase tracking-widest whitespace-nowrap"
                    >
                        <X className="w-3.5 h-3.5" />
                        Limpar Filtros
                    </button>
                )}
            </div>
        </div>
    )
}

'use client'

import { 
    Printer, 
    Pencil, 
    Trash2, 
    CheckCircle2, 
    Play, 
    XCircle, 
    ShieldCheck, 
    Wrench
} from 'lucide-react'
import { useState, useTransition } from 'react'
import { 
    deleteOrdemServico, 
    cancelOrdemServico, 
    finishOrdemServico, 
    approveOrdemServicoPlan,
    resumeOrdemServicoExecution 
} from '@/app/actions/pcm-actions'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { toast } from 'sonner'

interface OsRowActionsProps {
    osId: string
    osNumero: string
    status: string
}

export default function OsRowActions({ osId, osNumero, status }: OsRowActionsProps) {
    const [isDeleting, setIsDeleting] = useState(false)
    const [isPending, startTransition] = useTransition()
    const router = useRouter()

    const handleAction = async (action: (id: string) => Promise<any>, label: string) => {
        if (isPending) return
        
        startTransition(async () => {
            const res = await action(osId)
            if (res.success) {
                toast.success(`OS #${osNumero}: ${label} com sucesso!`)
                router.refresh()
            } else {
                toast.error(res.error || `Erro ao ${label.toLowerCase()} OS`)
            }
        })
    }

    const handleDelete = async () => {
        if (!confirm(`Deseja realmente excluir permanentemente a OS #${osNumero}?`)) return
        setIsDeleting(true)
        const res = await deleteOrdemServico(osId)
        if (res.success) {
            toast.success(`OS #${osNumero} excluída.`)
            router.refresh()
        } else {
            toast.error(res.error)
            setIsDeleting(false)
        }
    }

    return (
        <div className="flex items-center justify-end gap-2 group/actions">
            {/* Status-specific actions */}
            {(status === 'ABERTA' || status === 'PLANEJADA') && (
                <button
                    onClick={() => handleAction(resumeOrdemServicoExecution, 'Iniciada')}
                    disabled={isPending}
                    title="Iniciar Execução"
                    className="group relative w-10 h-10 rounded-2xl bg-primary/10 hover:bg-primary text-primary hover:text-white transition-all duration-300 flex items-center justify-center border border-primary/20 hover:scale-110 hover:shadow-[0_0_20px_-5px_var(--primary)] disabled:opacity-50"
                >
                    <Play className="w-4 h-4 fill-current transition-transform group-hover:scale-90" />
                    <span className="absolute -top-12 left-1/2 -translate-x-1/2 px-3 py-1.5 rounded-xl bg-gray-900/90 text-[10px] font-black uppercase tracking-widest text-white opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none whitespace-nowrap">Iniciar Execução</span>
                </button>
            )}

            {status === 'PLANEJADA' && (
                <button
                    onClick={() => handleAction(approveOrdemServicoPlan, 'Plano Aprovado')}
                    disabled={isPending}
                    title="Aprovar Plano"
                    className="group relative w-10 h-10 rounded-2xl bg-emerald-500/10 hover:bg-emerald-500 text-emerald-500 hover:text-white transition-all duration-300 flex items-center justify-center border border-emerald-500/20 hover:scale-110 hover:shadow-[0_0_20px_-5px_#10b981] disabled:opacity-50"
                >
                    <ShieldCheck className="w-4 h-4 transition-transform group-hover:rotate-12" />
                    <span className="absolute -top-12 left-1/2 -translate-x-1/2 px-3 py-1.5 rounded-xl bg-gray-900/90 text-[10px] font-black uppercase tracking-widest text-white opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none whitespace-nowrap">Aprovar Plano</span>
                </button>
            )}

            {status === 'EM_EXECUCAO' && (
                <button
                    onClick={() => handleAction(finishOrdemServico, 'Concluída')}
                    disabled={isPending}
                    title="Finalizar Ordem"
                    className="group relative w-10 h-10 rounded-2xl bg-blue-500/10 hover:bg-blue-500 text-blue-500 hover:text-white transition-all duration-300 flex items-center justify-center border border-blue-500/20 hover:scale-110 hover:shadow-[0_0_20px_-5px_#3b82f6] disabled:opacity-50"
                >
                    <CheckCircle2 className="w-4 h-4 transition-transform group-hover:scale-110 shadow-current" />
                    <span className="absolute -top-12 left-1/2 -translate-x-1/2 px-3 py-1.5 rounded-xl bg-gray-900/90 text-[10px] font-black uppercase tracking-widest text-white opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none whitespace-nowrap">Finalizar Ordem</span>
                </button>
            )}

            {(status === 'ABERTA' || status === 'PLANEJADA' || status === 'EM_EXECUCAO') && (
                <button
                    onClick={() => handleAction(cancelOrdemServico, 'Cancelada')}
                    disabled={isPending}
                    title="Cancelar O.S."
                    className="group relative w-10 h-10 rounded-2xl bg-red-500/10 hover:bg-red-500 text-red-500 hover:text-white transition-all duration-300 flex items-center justify-center border border-red-500/20 hover:scale-110 hover:shadow-[0_0_20px_-5px_#ef4444] disabled:opacity-50"
                >
                    <XCircle className="w-4 h-4" />
                    <span className="absolute -top-12 left-1/2 -translate-x-1/2 px-3 py-1.5 rounded-xl bg-gray-900/90 text-[10px] font-black uppercase tracking-widest text-white opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 pointer-events-none whitespace-nowrap">Cancelar OS</span>
                </button>
            )}

            <div className="w-px h-6 bg-border-color/50 mx-1" />

            {/* Standard actions */}
            <Link
                href={`/print/os/${osId}`}
                target="_blank"
                title="Imprimir O.S."
                className="w-8 h-8 rounded-xl bg-surface-highlight hover:bg-white/10 text-gray-400 hover:text-white transition-all flex items-center justify-center border border-white/5 active:scale-95"
            >
                <Printer className="w-4 h-4 opacity-70" />
            </Link>
            
            <Link
                href={`/dashboard/pcm/os/editar/${osId}`}
                title="Editar O.S."
                className="w-8 h-8 rounded-xl bg-surface-highlight hover:bg-white/10 text-gray-400 hover:text-white transition-all flex items-center justify-center border border-white/5 active:scale-95"
            >
                <Pencil className="w-4 h-4 opacity-70" />
            </Link>

            {status !== 'CONCLUIDA' && status !== 'CANCELADA' && (
                <button
                    onClick={handleDelete}
                    disabled={isDeleting || isPending}
                    title="Excluir Definitivamente"
                    className="w-8 h-8 rounded-xl bg-surface-highlight hover:bg-red-500/10 text-gray-400 hover:text-red-500 transition-all flex items-center justify-center border border-white/5 active:scale-95"
                >
                    <Trash2 className="w-4 h-4" />
                </button>
            )}
        </div>
    )
}

'use client'

import { useState } from 'react'
import { Plus, Filter, Search, MoreHorizontal, Calendar, Wrench, AlertCircle, CheckCircle2, Trash2, Loader2 } from 'lucide-react'
import Link from 'next/link'
import { OrdemServico, Veiculo } from '@prisma/client'
import OsRowActions from './OsRowActions'
import { deleteMultipleOrdensServico } from '@/app/actions/pcm-actions'
import { toast } from 'sonner'

type OrdemServicoComVeiculo = OrdemServico & { veiculo: Veiculo }

interface OsTableProps {
    ordens: OrdemServicoComVeiculo[]
}

export default function OsTable({ ordens }: OsTableProps) {
    const [selectedIds, setSelectedIds] = useState<string[]>([])
    const [isDeleting, setIsDeleting] = useState(false)

    const toggleSelectAll = () => {
        if (selectedIds.length === ordens.length) {
            setSelectedIds([])
        } else {
            setSelectedIds(ordens.map(os => os.id))
        }
    }

    const toggleSelectRow = (id: string) => {
        if (selectedIds.includes(id)) {
            setSelectedIds(selectedIds.filter(i => i !== id))
        } else {
            setSelectedIds([...selectedIds, id])
        }
    }

    const handleMassDelete = async () => {
        if (selectedIds.length === 0) return

        if (!confirm(`Deseja realmente excluir as ${selectedIds.length} Ordens de Serviço selecionadas?`)) {
            return
        }

        setIsDeleting(true)
        try {
            const result = await deleteMultipleOrdensServico(selectedIds)
            if (result.success) {
                toast.success(`${selectedIds.length} O.S. excluídas com sucesso`)
                setSelectedIds([])
            } else {
                toast.error(result.error || 'Erro ao excluir O.S.')
            }
        } catch (error) {
            toast.error('Erro de conexão ao excluir O.S.')
        } finally {
            setIsDeleting(false)
        }
    }

    return (
        <div className="bg-surface border border-border-color rounded-3xl overflow-hidden shadow-sm relative group/table transition-all duration-500 hover:shadow-xl hover:shadow-black/5">
            {/* Mass Actions Bar */}
            {selectedIds.length > 0 && (
                <div className="absolute top-0 left-0 right-0 z-20 h-16 bg-surface-highlight flex items-center justify-between px-8 animate-in slide-in-from-top duration-300 border-b border-border-color">
                    <div className="flex items-center gap-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-primary animate-pulse">
                            {selectedIds.length} O.S. Selecionadas
                        </span>
                        <div className="h-4 w-[1px] bg-border-color mx-2" />
                        <button 
                            onClick={() => setSelectedIds([])}
                            className="text-[10px] font-bold text-gray-500 hover:text-foreground transition-colors uppercase tracking-widest"
                        >
                            Cancelar
                        </button>
                    </div>
                    <button
                        onClick={handleMassDelete}
                        disabled={isDeleting}
                        className="bg-red-500 hover:bg-red-600 disabled:opacity-50 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-red-500/20 transition-all hover:scale-[1.02] active:scale-[0.98]"
                    >
                        {isDeleting ? (
                            <Loader2 className="w-3.5 h-3.5 animate-spin" />
                        ) : (
                            <Trash2 className="w-3.5 h-3.5" />
                        )}
                        Excluir Selecionadas
                    </button>
                </div>
            )}

            <div className="overflow-x-auto scrollbar-thin scrollbar-track-transparent scrollbar-thumb-border-color">
                <table className="w-full text-left border-collapse min-w-[1000px]">
                    <thead>
                        <tr className="bg-surface-secondary/30">
                            <th className="px-8 py-5 border-b border-border-color w-10">
                                <div className="flex items-center justify-center">
                                    <input 
                                        type="checkbox" 
                                        className="w-4 h-4 rounded border-border-color bg-surface text-primary focus:ring-primary/20 accent-primary cursor-pointer transition-all"
                                        checked={ordens.length > 0 && selectedIds.length === ordens.length}
                                        onChange={toggleSelectAll}
                                    />
                                </div>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">O.S. / Veículo</span>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Tipo</span>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Descrição</span>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Abertura</span>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color text-center">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Status</span>
                            </th>
                            <th className="px-8 py-5 border-b border-border-color text-right">
                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Ações</span>
                            </th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border-color/50">
                        {ordens.length > 0 ? (
                            ordens.map((os) => (
                                <tr 
                                    key={os.id} 
                                    className={`group hover:bg-surface-highlight/50 transition-all duration-300 ${selectedIds.includes(os.id) ? 'bg-primary/5' : ''}`}
                                >
                                    <td className="px-8 py-6">
                                        <div className="flex items-center justify-center">
                                            <input 
                                                type="checkbox" 
                                                className="w-4 h-4 rounded border-border-color bg-surface text-primary focus:ring-primary/20 accent-primary cursor-pointer transition-all"
                                                checked={selectedIds.includes(os.id)}
                                                onChange={() => toggleSelectRow(os.id)}
                                            />
                                        </div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 rounded-2xl bg-surface-highlight flex items-center justify-center border border-border-color shadow-sm group-hover:scale-110 transition-transform duration-500 overflow-hidden relative">
                                                <div className="absolute inset-0 bg-primary/5 opacity-0 group-hover:opacity-100 transition-opacity" />
                                                <Wrench className="w-4 h-4 text-primary" />
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="font-black text-foreground text-[11px] tracking-widest mb-0.5">#{os.numeroOS.toString().padStart(5, '0')}</span>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[9px] font-bold text-gray-400 group-hover:text-primary transition-colors cursor-default uppercase">
                                                        {os.veiculo.modelo}
                                                    </span>
                                                    <span className="text-[8px] px-1.5 py-0.5 rounded bg-surface-secondary text-gray-500 font-bold border border-border-color">
                                                        {os.veiculo.placa}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <BadgeTipo tipo={os.tipoOS} />
                                    </td>
                                    <td className="px-8 py-6 max-w-md">
                                        <p className="text-gray-500 dark:text-gray-400 text-[11px] font-bold leading-relaxed line-clamp-2 italic opacity-80 group-hover:opacity-100 transition-opacity" title={os.descricao}>
                                            &ldquo;{os.descricao}&rdquo;
                                        </p>
                                    </td>
                                    <td className="px-8 py-6">
                                        <div className="flex flex-col">
                                            <span className="font-black text-foreground text-[10px] tracking-widest mb-0.5">
                                                {new Date(os.dataAbertura).toLocaleDateString('pt-BR')}
                                            </span>
                                            <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">
                                                {new Date(os.dataAbertura).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-8 py-6 text-center">
                                        <BadgeStatus status={os.status} />
                                    </td>
                                    <td className="px-8 py-6 text-right">
                                        <OsRowActions
                                            osId={os.id}
                                            osNumero={os.numeroOS.toString().padStart(5, '0')}
                                            status={os.status}
                                        />
                                    </td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={7} className="px-8 py-32 text-center">
                                    <div className="flex flex-col items-center justify-center bg-surface-highlight/5 rounded-3xl p-12 border-2 border-dashed border-border-color max-w-md mx-auto">
                                        <div className="w-20 h-20 rounded-full bg-surface-highlight flex items-center justify-center mb-6 shadow-inner relative">
                                            <Wrench className="w-8 h-8 text-gray-400 opacity-20" />
                                            <Search className="w-5 h-5 text-primary absolute -bottom-1 -right-1" />
                                        </div>
                                        <h3 className="text-lg font-black text-foreground mb-2">Histórico não Localizado</h3>
                                        <p className="text-xs text-gray-500 mb-8 max-w-xs mx-auto font-medium">Nenhuma Ordem de Serviço corresponde aos filtros aplicados. Tente ajustar sua busca.</p>
                                        <Link href="/dashboard/pcm/os">
                                            <button className="text-primary font-black text-[10px] hover:underline uppercase tracking-widest bg-primary/10 px-6 py-2.5 rounded-xl border border-primary/20 transition-all hover:bg-primary/20">
                                                Limpar Filtros
                                            </button>
                                        </Link>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    )
}

function BadgeTipo({ tipo }: { tipo: string }) {
    const styles: Record<string, string> = {
        PREVENTIVA: 'bg-blue-500/10 text-blue-500 border-blue-500/20',
        CORRETIVA: 'bg-red-500/10 text-red-500 border-red-500/20',
        INSPECAO: 'bg-purple-500/10 text-purple-500 border-purple-500/20',
        MELHORIA: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    }
    const safeStyle = styles[tipo] || 'bg-gray-500/10 text-gray-500 border-gray-500/20'

    return (
        <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border ${safeStyle}`}>
            {tipo}
        </span>
    )
}

function BadgeStatus({ status }: { status: string }) {
    const styles: Record<string, { bg: string, text: string, dot: string }> = {
        ABERTA: { bg: 'bg-gray-500/5', text: 'text-gray-500', dot: 'bg-gray-500' },
        PLANEJADA: { bg: 'bg-yellow-500/5', text: 'text-yellow-500', dot: 'bg-yellow-500' },
        EM_EXECUCAO: { bg: 'bg-orange-500/5', text: 'text-orange-500', dot: 'bg-orange-500 animate-pulse' },
        CONCLUIDA: { bg: 'bg-emerald-500/5', text: 'text-emerald-500', dot: 'bg-emerald-500' },
        CANCELADA: { bg: 'bg-red-500/5', text: 'text-red-500', dot: 'bg-red-500' },
    }
    const config = styles[status] || styles.ABERTA

    return (
        <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full border border-current/10 ${config.bg} ${config.text}`}>
            {status === 'CONCLUIDA' ? (
                <CheckCircle2 className="w-3.5 h-3.5" />
            ) : status === 'CANCELADA' ? (
                <AlertCircle className="w-3.5 h-3.5" />
            ) : (
                <div className={`w-1.5 h-1.5 rounded-full ${config.dot}`} />
            )}
            <span className="text-[10px] font-black uppercase tracking-widest leading-none">{status.replace('_', ' ')}</span>
        </div>
    )
}

'use client'

import { updateOrdemServico } from '@/app/actions/pcm-actions'
import { ArrowLeft, Calendar, Clock, CheckCircle2, List, Search, ChevronDown } from 'lucide-react'
import Link from 'next/link'
import { useState } from 'react'
import { useRouter } from 'next/navigation'

interface VeiculoDropdown {
    id: string;
    codigoInterno: string;
    modelo: string;
    placa: string | null;
}

interface OsMotivo {
    id: string;
    nome: string;
}

interface OsSubSistema {
    id: string;
    nome: string;
    sistemaId: string;
}

interface OsSistema {
    id: string;
    nome: string;
    subSistemas: OsSubSistema[];
}

interface OrdemServicoData {
    id: string;
    veiculoId: string;
    tipoOS: string;
    status: string;
    descricao: string;
    dataAbertura: Date;
    dataConclusao: Date | null;
    horimetro: number | null;
    motivoId: string | null;
    sistemaId: string | null;
    subSistemaId: string | null;
    local: string | null;
    modulo: string | null;
    veiculoReservaId: string | null;
}

export default function EditarOSForm({ veiculos, osOptions, initialData }: {
    veiculos: VeiculoDropdown[],
    osOptions: { motivos: OsMotivo[], sistemas: OsSistema[] },
    initialData: OrdemServicoData
}) {
    const router = useRouter()
    const [selectedSistemaId, setSelectedSistemaId] = useState<string>(initialData.sistemaId || '')
    const [descricao, setDescricao] = useState(initialData.descricao)
    const [isSuccess, setIsSuccess] = useState(false)
    const [statusOS, setStatusOS] = useState(initialData.status === 'CONCLUIDA' ? 'FECHADA' : initialData.status)

    // Searchable Vehicle Selection
    const [searchTerm, setSearchTerm] = useState('')
    const [isDropdownOpen, setIsDropdownOpen] = useState(false)
    const [selectedVeiculo, setSelectedVeiculo] = useState<VeiculoDropdown | undefined>(() =>
        veiculos.find(v => v.id === initialData.veiculoId)
    )

    const filteredVeiculos = veiculos.filter(v =>
        v.codigoInterno.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (v.placa && v.placa.toLowerCase().includes(searchTerm.toLowerCase())) ||
        v.modelo.toLowerCase().includes(searchTerm.toLowerCase())
    )

    const filteredSubSistemas = osOptions.sistemas.find(s => s.id === selectedSistemaId)?.subSistemas || []

    const handleDescricaoKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter') {
            const cursorPosition = e.currentTarget.selectionStart;
            const textBeforeCursor = descricao.slice(0, cursorPosition);
            const textAfterCursor = descricao.slice(cursorPosition);

            const lines = textBeforeCursor.split('\n');
            const lastLine = lines[lines.length - 1];

            const match = lastLine.match(/^(\d+)([.\-)]\s*)(.*)$/);

            if (match) {
                e.preventDefault();
                if (match[3].trim() === '') {
                    const withoutNumber = textBeforeCursor.slice(0, cursorPosition - lastLine.length);
                    const newText = withoutNumber + '\n' + textAfterCursor;
                    setDescricao(newText);
                    setTimeout(() => {
                        const ta = document.getElementsByName('descricao')[0] as HTMLTextAreaElement;
                        if (ta) ta.selectionStart = ta.selectionEnd = withoutNumber.length + 1;
                    }, 0);
                    return;
                }
                const currentNumber = parseInt(match[1], 10);
                const separator = match[2];
                const insertText = `\n${currentNumber + 1}${separator}`;
                const newText = textBeforeCursor + insertText + textAfterCursor;
                setDescricao(newText);
                setTimeout(() => {
                    const ta = document.getElementsByName('descricao')[0] as HTMLTextAreaElement;
                    if (ta) {
                        const newPos = cursorPosition + insertText.length;
                        ta.selectionStart = ta.selectionEnd = newPos;
                    }
                }, 0);
            }
        }
    };

    if (isSuccess) {
        return (
            <div className="max-w-2xl mx-auto py-20 text-center space-y-8 animate-in fade-in zoom-in-95 duration-500">
                <div className="flex justify-center">
                    <div className="w-24 h-24 rounded-full bg-emerald-500/10 flex items-center justify-center border-4 border-emerald-500/20">
                        <CheckCircle2 className="w-12 h-12 text-emerald-500" />
                    </div>
                </div>

                <div className="space-y-2">
                    <h1 className="text-3xl font-black text-foreground tracking-tight">O.S. Atualizada com Sucesso!</h1>
                    <p className="text-gray-500 font-bold uppercase text-xs tracking-widest">
                        As alterações foram salvas no histórico do sistema.
                    </p>
                </div>

                <div className="flex justify-center pt-8">
                    <Link href="/dashboard/pcm/os">
                        <button className="flex items-center justify-center gap-3 bg-primary hover:bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:shadow-xl hover:shadow-primary/20 hover:-translate-y-1">
                            <List className="w-5 h-5" />
                            Ver Histórico
                        </button>
                    </Link>
                </div>
            </div>
        )
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <Link href="/dashboard/pcm/os" className="text-gray-500 hover:text-primary text-xs font-bold flex items-center gap-1 mb-2 transition-colors uppercase tracking-widest">
                        <ArrowLeft className="w-3 h-3" /> Voltar ao Controle
                    </Link>
                    <h1 className="text-3xl font-bold text-foreground tracking-tight">Editar O.S.</h1>
                    <p className="text-gray-500 text-sm mt-1">Atualize as informações da Ordem de Serviço #{initialData.id.slice(-5)}</p>
                </div>
                <div className="p-3 bg-primary/10 rounded-2xl">
                    <Clock className="w-8 h-8 text-primary" />
                </div>
            </div>

            <div className="dashboard-card p-8">
                <form action={async (formData) => {
                    const res = await updateOrdemServico(initialData.id, formData)
                    if (res.success) {
                        setIsSuccess(true)
                    } else {
                        alert(res.error || 'Erro ao atualizar a OS.')
                    }
                }} className="space-y-10">

                    {/* Section: Basic Info */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 border-l-4 border-primary pl-4">
                            <h2 className="text-sm font-black uppercase tracking-widest text-foreground">Informações Básicas</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-2 relative">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Veículo / Placa *</label>
                                <div className="relative group">
                                    <input
                                        type="hidden"
                                        name="veiculoId"
                                        value={selectedVeiculo?.id || ''}
                                        required
                                    />
                                    <div
                                        onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                                        className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold flex items-center justify-between cursor-pointer hover:border-primary/50 transition-all shadow-sm"
                                    >
                                        <div className="flex items-center gap-3">
                                            {selectedVeiculo ? (
                                                <div className="flex items-center gap-2">
                                                    <span className="text-primary font-black">{selectedVeiculo.codigoInterno}</span>
                                                    <span className="text-gray-400">|</span>
                                                    <span>{selectedVeiculo.modelo} ({selectedVeiculo.placa || 'Interno'})</span>
                                                </div>
                                            ) : (
                                                <span className="text-gray-500 font-medium italic">Selecione o Veículo</span>
                                            )}
                                        </div>
                                        <ChevronDown className={`w-4 h-4 text-gray-500 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                                    </div>

                                    {isDropdownOpen && (
                                        <div className="absolute top-full left-0 right-0 mt-2 bg-surface border border-border-color rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                                            <div className="p-3 border-b border-border-color bg-surface-highlight/30 flex items-center gap-3">
                                                <Search className="w-4 h-4 text-primary shrink-0" />
                                                <input
                                                    type="text"
                                                    autoFocus
                                                    placeholder="Buscar por placa, código ou modelo..."
                                                    value={searchTerm}
                                                    onChange={(e) => setSearchTerm(e.target.value)}
                                                    className="w-full bg-transparent border-none outline-none text-xs font-bold text-foreground placeholder:text-gray-500"
                                                />
                                            </div>
                                            <div className="max-h-64 overflow-y-auto custom-scrollbar">
                                                {filteredVeiculos.length > 0 ? (
                                                    filteredVeiculos.map((v) => (
                                                        <div
                                                            key={v.id}
                                                            onClick={() => {
                                                                setSelectedVeiculo(v)
                                                                setIsDropdownOpen(false)
                                                                setSearchTerm('')
                                                            }}
                                                            className={`px-4 py-3 hover:bg-primary/10 cursor-pointer transition-colors flex items-center gap-4 group ${selectedVeiculo?.id === v.id ? 'bg-primary/5' : ''}`}
                                                        >
                                                            <div className="w-12 py-1 rounded-lg bg-surface-highlight border border-border-color flex items-center justify-center group-hover:border-primary/40 transition-all bg-gray-500/5">
                                                                <span className="text-[10px] font-black text-foreground">{v.codigoInterno}</span>
                                                            </div>
                                                            <div className="flex flex-col">
                                                                <span className="text-[11px] font-black text-foreground uppercase">{v.placa || 'INTERNO'}</span>
                                                                <span className="text-[9px] font-bold text-gray-500 uppercase tracking-widest">{v.modelo}</span>
                                                            </div>
                                                            {selectedVeiculo?.id === v.id && (
                                                                <div className="ml-auto">
                                                                    <CheckCircle2 className="w-4 h-4 text-primary" />
                                                                </div>
                                                            )}
                                                        </div>
                                                    ))
                                                ) : (
                                                    <div className="px-4 py-8 text-center text-gray-500 text-xs italic font-medium">
                                                        Nenhum veículo localizado
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    )}
                                </div>
                                {isDropdownOpen && (
                                    <div
                                        className="fixed inset-0 z-40 bg-transparent"
                                        onClick={() => setIsDropdownOpen(false)}
                                    />
                                )}
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Tipo de Manutenção *</label>
                                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                                    {['CORRETIVA', 'PREVENTIVA', 'INSPECAO', 'MELHORIA'].map(tipo => (
                                        <label key={tipo} className="cursor-pointer">
                                            <input type="radio" name="tipoOS" value={tipo} className="peer hidden" defaultChecked={tipo === initialData.tipoOS} />
                                            <div className="text-center py-3 rounded-xl border border-border-color font-bold text-[10px] transition-all peer-checked:bg-primary/10 peer-checked:border-primary peer-checked:text-primary hover:bg-surface-highlight uppercase tracking-tighter">
                                                {tipo}
                                            </div>
                                        </label>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Data/Hora Abertura *</label>
                                <div className="relative">
                                    <input type="datetime-local" name="dataAbertura" defaultValue={new Date(initialData.dataAbertura).toISOString().slice(0, 16)} required className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all pl-11" />
                                    <Calendar className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-500 pointer-events-none" />
                                </div>
                            </div>

                            <div className="space-y-2 animate-in fade-in zoom-in-95 duration-300">
                                <label className="text-[10px] uppercase font-black text-primary tracking-widest ml-1">
                                    Data/Hora Fechamento {statusOS === 'FECHADA' && '*'}
                                </label>
                                <div className="relative">
                                    <input
                                        type="datetime-local"
                                        name="dataConclusao"
                                        defaultValue={initialData.dataConclusao ? new Date(initialData.dataConclusao).toISOString().slice(0, 16) : ''}
                                        required={statusOS === 'FECHADA'}
                                        className="w-full bg-background border border-primary/30 rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all pl-11"
                                    />
                                    <Calendar className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-500 pointer-events-none" />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Status</label>
                                <select
                                    name="status"
                                    value={statusOS}
                                    onChange={(e) => setStatusOS(e.target.value)}
                                    className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer"
                                >
                                    <option value="ABERTA">ABERTA</option>
                                    <option value="EM_EXECUCAO">EM EXECUÇÃO</option>
                                    <option value="PLANEJADA">PLANEJADA</option>
                                    <option value="FECHADA">FECHADA</option>
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Horímetro / Km</label>
                                <input type="number" name="horimetro" defaultValue={initialData.horimetro || ''} placeholder="Ex: 1450" className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                            </div>
                        </div>
                    </div>

                    {/* Section: Detailed Diagnosis */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 border-l-4 border-primary pl-4">
                            <h2 className="text-sm font-black uppercase tracking-widest text-foreground">Diagnóstico & Local</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Motivo / Causa</label>
                                <select name="motivoId" defaultValue={initialData.motivoId || ''} className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer">
                                    <option value="">Selecione o Motivo</option>
                                    {osOptions.motivos.map(m => (
                                        <option key={m.id} value={m.id}>{m.nome}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Sistema Afetado</label>
                                <select
                                    name="sistemaId"
                                    value={selectedSistemaId}
                                    onChange={(e) => setSelectedSistemaId(e.target.value)}
                                    className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer"
                                >
                                    <option value="">Selecione o Sistema</option>
                                    {osOptions.sistemas.map(s => (
                                        <option key={s.id} value={s.id}>{s.nome}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Sub-Sistema</label>
                                <select name="subSistemaId" defaultValue={initialData.subSistemaId || ''} className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer">
                                    <option value="">Selecione o Sub-Sistema</option>
                                    {filteredSubSistemas.map((ss: OsSubSistema) => (
                                        <option key={ss.id} value={ss.id}>{ss.nome}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Descrição Detalhada do Problema *</label>
                            <textarea
                                name="descricao"
                                rows={6}
                                required
                                value={descricao}
                                onChange={(e) => setDescricao(e.target.value)}
                                onKeyDown={handleDescricaoKeyDown}
                                className="w-full bg-background border border-border-color rounded-xl px-4 py-4 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all resize-none shadow-inner"
                            />
                        </div>
                    </div>

                    {/* Section: Logistics */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 border-l-4 border-primary pl-4">
                            <h2 className="text-sm font-black uppercase tracking-widest text-foreground">Logística & Apoio</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-start">
                            <div className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase font-black text-primary tracking-widest ml-1">Veículo Reserva Enviado</label>
                                    <select name="veiculoReservaId" defaultValue={initialData.veiculoReservaId || ''} className="w-full bg-background border border-primary/30 rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer">
                                        <option value="">Selecione o reserva...</option>
                                        {veiculos.map((v) => (
                                            <option key={v.id} value={v.id}>{v.codigoInterno} - {v.placa}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Local do Equipamento</label>
                                    <input type="text" name="local" defaultValue={initialData.local || ''} placeholder="Ex: Frente 02, Oficina Sul..." className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Módulo / Equipamento Específico</label>
                                    <input type="text" name="modulo" defaultValue={initialData.modulo || ''} placeholder="Ex: Motor, Caçamba, Implemento..." className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="pt-8 border-t border-border-color flex flex-col sm:flex-row justify-end gap-4">
                        <Link href="/dashboard/pcm/os" className="w-full sm:w-auto">
                            <button type="button" className="w-full px-8 py-3.5 rounded-xl border border-border-color text-gray-400 font-bold hover:bg-surface-highlight transition-all uppercase text-[10px] tracking-widest">
                                Cancelar
                            </button>
                        </Link>
                        <button type="submit" className="w-full sm:w-auto bg-primary hover:bg-blue-600 text-white px-12 py-3.5 rounded-xl font-black flex items-center justify-center gap-2 transition-all shadow-lg shadow-primary/25 hover:shadow-primary/40 active:scale-[0.98] uppercase text-[10px] tracking-widest">
                            <Clock className="w-4 h-4 stroke-[3px]" />
                            Salvar Alterações
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

'use client'

import { createOrdemServico } from '@/app/actions/pcm-actions'
import { getBacklogByVehicle } from '@/app/actions/backlog-actions'
import { ArrowLeft, Calendar, Clock, Loader2, CheckCircle2, Printer, List } from 'lucide-react'
import Link from 'next/link'
import { SearchableSelect } from '@/components/ui/SearchableSelect'
import { useState } from 'react'
import { useRouter } from 'next/navigation'

interface VeiculoDropdown {
    id: string;
    codigoInterno: string;
    modelo: string;
    placa: string | null;
}

interface OsMotivo {
    id: string;
    nome: string;
}

interface OsSubSistema {
    id: string;
    nome: string;
    sistemaId: string;
}

interface OsSistema {
    id: string;
    nome: string;
    subSistemas: OsSubSistema[];
}

export default function NovaOSForm({ veiculos, osOptions }: {
    veiculos: VeiculoDropdown[],
    osOptions: { motivos: OsMotivo[], sistemas: OsSistema[] }
}) {
    const router = useRouter()
    const [enviadoReserva, setEnviadoReserva] = useState(false)
    const [selectedSistemaId, setSelectedSistemaId] = useState<string>('')
    const [descricao, setDescricao] = useState('')
    const [isFetchingBacklog, setIsFetchingBacklog] = useState(false)
    const [isSuccess, setIsSuccess] = useState(false)
    const [lastCreatedOS, setLastCreatedOS] = useState<string | null>(null)
    const [statusOS, setStatusOS] = useState('ABERTA')

    const filteredSubSistemas = osOptions.sistemas.find(s => s.id === selectedSistemaId)?.subSistemas || []

    const veiculoOptions = veiculos.map(v => ({
        value: v.id,
        label: `${v.codigoInterno} - ${v.modelo} (${v.placa || 'Interno'})`
    }))

    const handleVeiculoChange = async (veiculoId: string) => {
        if (!veiculoId) return

        const veiculo = veiculos.find(v => v.id === veiculoId)
        if (!veiculo) return

        setIsFetchingBacklog(true)
        // Buscamos o código interno e placa para garantir o match
        const identifiers = [veiculo.codigoInterno, veiculo.placa].filter(Boolean) as string[]
        const res = await getBacklogByVehicle(identifiers)

        if (res.success && res.data && res.data.length > 0) {
            const backlogText = res.data
                .map(item => `• ${item.descricaoAtividade}${item.criticidade ? ` [${item.criticidade}]` : ''}`)
                .join('\n')

            const novoTexto = `PENDÊNCIAS DO BACKLOG:\n${backlogText}`

            // Se já houver descrição, adicionamos ao fim, senão substituímos
            setDescricao(prev => {
                if (!prev) return novoTexto
                if (prev.includes('PENDÊNCIAS DO BACKLOG:')) {
                    // Substituir bloco antigo se o usuário trocar de veículo
                    return prev.replace(/PENDÊNCIAS DO BACKLOG:[\s\S]*/g, novoTexto)
                }
                return `${prev}\n\n${novoTexto}`
            })
        }
        setIsFetchingBacklog(false)
    }

    const handleDescricaoKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter') {
            const cursorPosition = e.currentTarget.selectionStart;
            const textBeforeCursor = descricao.slice(0, cursorPosition);
            const textAfterCursor = descricao.slice(cursorPosition);

            const lines = textBeforeCursor.split('\n');
            const lastLine = lines[lines.length - 1];

            // Match numbered line e.g., "1. ", "1- ", "1) "
            const match = lastLine.match(/^(\d+)([.\-)]\s*)(.*)$/);

            if (match) {
                e.preventDefault();

                // If it's an empty numbered line, pressing Enter removes the number to break the list
                if (match[3].trim() === '') {
                    const withoutNumber = textBeforeCursor.slice(0, cursorPosition - lastLine.length);
                    const newText = withoutNumber + '\n' + textAfterCursor;
                    setDescricao(newText);

                    setTimeout(() => {
                        const ta = document.getElementsByName('descricao')[0] as HTMLTextAreaElement;
                        if (ta) ta.selectionStart = ta.selectionEnd = withoutNumber.length + 1;
                    }, 0);
                    return;
                }

                // Normal populated item, go to next number
                const currentNumber = parseInt(match[1], 10);
                const separator = match[2];
                const insertText = `\n${currentNumber + 1}${separator}`;

                const newText = textBeforeCursor + insertText + textAfterCursor;
                setDescricao(newText);

                setTimeout(() => {
                    const ta = document.getElementsByName('descricao')[0] as HTMLTextAreaElement;
                    if (ta) {
                        const newPos = cursorPosition + insertText.length;
                        ta.selectionStart = ta.selectionEnd = newPos;
                    }
                }, 0);
            }
        }
    };

    const handleDescricaoFocus = () => {
        if (descricao.trim() === '') {
            setDescricao('1. ');
        } else if (!descricao.includes('1. ') && !descricao.includes('PENDÊNCIAS')) {
            // Se já tem algum texto mas não tem número e não é backlog, a gente converte
            setDescricao(`1. ${descricao}`);
        }
    };

    if (isSuccess) {
        return (
            <div className="max-w-2xl mx-auto py-20 text-center space-y-8 animate-in fade-in zoom-in-95 duration-500">
                <div className="flex justify-center">
                    <div className="w-24 h-24 rounded-full bg-emerald-500/10 flex items-center justify-center border-4 border-emerald-500/20">
                        <CheckCircle2 className="w-12 h-12 text-emerald-500" />
                    </div>
                </div>

                <div className="space-y-2">
                    <h1 className="text-3xl font-black text-foreground tracking-tight">O.S. Aberta com Sucesso!</h1>
                    <p className="text-gray-500 font-bold uppercase text-xs tracking-widest">
                        A Ordem de Serviço foi registrada no histórico do sistema.
                    </p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-8">
                    {lastCreatedOS ? (
                        <Link
                            href={`/print/os/${lastCreatedOS}`}
                            target="_blank"
                            className="flex items-center justify-center gap-3 bg-surface border-2 border-border-color hover:border-primary/50 text-foreground px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:shadow-xl hover:-translate-y-1"
                        >
                            <Printer className="w-5 h-5 text-primary" />
                            Imprimir O.S.
                        </Link>
                    ) : (
                        <button
                            onClick={() => window.print()}
                            className="flex items-center justify-center gap-3 bg-surface border-2 border-border-color hover:border-primary/50 text-foreground px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:shadow-xl hover:-translate-y-1"
                        >
                            <Printer className="w-5 h-5 text-primary" />
                            Imprimir O.S.
                        </button>
                    )}
                    <Link href="/dashboard/pcm/os">
                        <button className="w-full flex items-center justify-center gap-3 bg-primary hover:bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:shadow-xl hover:shadow-primary/20 hover:-translate-y-1">
                            <List className="w-5 h-5" />
                            Ver Histórico
                        </button>
                    </Link>
                </div>

                <button
                    onClick={() => setIsSuccess(false)}
                    className="text-gray-400 font-bold text-[10px] uppercase tracking-widest hover:text-primary transition-colors"
                >
                    Abrir Nova Ordem de Serviço
                </button>
            </div>
        )
    }

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <div className="flex items-center justify-between">
                <div>
                    <Link href="/dashboard/pcm/os" className="text-gray-500 hover:text-primary text-xs font-bold flex items-center gap-1 mb-2 transition-colors uppercase tracking-widest">
                        <ArrowLeft className="w-3 h-3" /> Voltar ao Controle
                    </Link>
                    <h1 className="text-3xl font-bold text-foreground tracking-tight">Abertura de O.S.</h1>
                    <p className="text-gray-500 text-sm mt-1">Registre uma nova ocorrência de manutenção para a frota.</p>
                </div>
                <div className="p-3 bg-primary/10 rounded-2xl">
                    <Clock className="w-8 h-8 text-primary" />
                </div>
            </div>

            <div className="dashboard-card p-8">
                <form action={async (formData) => {
                    const res = await createOrdemServico(formData)
                    if (res.success && res.osId) {
                        setLastCreatedOS(res.osId)
                        setIsSuccess(true)
                    } else {
                        alert(res.error || 'Erro ao criar a OS.')
                    }
                }} className="space-y-10">

                    {/* Section: Basic Info */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 border-l-4 border-primary pl-4">
                            <h2 className="text-sm font-black uppercase tracking-widest text-foreground">Informações Básicas</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1 flex items-center gap-2">
                                    Veículo / Placa *
                                    {isFetchingBacklog && <Loader2 className="w-3 h-3 animate-spin text-primary" />}
                                </label>
                                <SearchableSelect
                                    name="veiculoId"
                                    options={veiculoOptions}
                                    placeholder="Selecione o Veículo"
                                    required
                                    onSelect={(value) => handleVeiculoChange(value)}
                                />

                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Tipo de Manutenção *</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['CORRETIVA', 'PREVENTIVA', 'MELHORIA'].map(tipo => (
                                        <label key={tipo} className="cursor-pointer">
                                            <input type="radio" name="tipoOS" value={tipo} className="peer hidden" defaultChecked={tipo === 'CORRETIVA'} />
                                            <div className="text-center py-3 rounded-xl border border-border-color font-bold text-[10px] transition-all peer-checked:bg-primary/10 peer-checked:border-primary peer-checked:text-primary hover:bg-surface-highlight uppercase tracking-tighter">
                                                {tipo}
                                            </div>
                                        </label>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Data/Hora Abertura *</label>
                                <div className="relative">
                                    <input type="datetime-local" name="dataAbertura" defaultValue={new Date().toISOString().slice(0, 16)} required className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all pl-11" />
                                    <Calendar className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-500 pointer-events-none" />
                                </div>
                            </div>

                            <div className="space-y-2 animate-in fade-in zoom-in-95 duration-300">
                                <label className="text-[10px] uppercase font-black text-primary tracking-widest ml-1">
                                    Data/Hora Fechamento {statusOS === 'FECHADA' && '*'}
                                </label>
                                <div className="relative">
                                    <input
                                        type="datetime-local"
                                        name="dataConclusao"
                                        defaultValue={statusOS === 'FECHADA' ? new Date().toISOString().slice(0, 16) : ''}
                                        required={statusOS === 'FECHADA'}
                                        className="w-full bg-background border border-primary/30 rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all pl-11"
                                    />
                                    <Calendar className="absolute left-3.5 top-3.5 w-5 h-5 text-gray-500 pointer-events-none" />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Status Inicial</label>
                                <select
                                    name="status"
                                    value={statusOS}
                                    onChange={(e) => setStatusOS(e.target.value)}
                                    className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer"
                                >
                                    <option value="ABERTA">ABERTA</option>
                                    <option value="EM_EXECUCAO">EM EXECUÇÃO</option>
                                    <option value="PLANEJADA">PLANEJADA</option>
                                    <option value="FECHADA">FECHADA</option>
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Horímetro / Km Atual</label>
                                <input type="number" name="horimetro" placeholder="Ex: 1450" className="w-full bg-background border border-border-color rounded-xl px-4 py-3 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all" />
                            </div>
                        </div>
                    </div>

                    {/* Section: Detailed Diagnosis */}
                    <div className="space-y-6">
                        <div className="flex items-center gap-3 border-l-4 border-primary pl-4">
                            <h2 className="text-sm font-black uppercase tracking-widest text-foreground">Diagnóstico & Local</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Motivo / Causa</label>
                                <select name="motivoId" className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer">
                                    <option value="">Selecione o Motivo</option>
                                    {osOptions.motivos.map(m => (
                                        <option key={m.id} value={m.id}>{m.nome}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Sistema Afetado</label>
                                <select
                                    name="sistemaId"
                                    value={selectedSistemaId}
                                    onChange={(e) => setSelectedSistemaId(e.target.value)}
                                    className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer"
                                >
                                    <option value="">Selecione o Sistema</option>
                                    {osOptions.sistemas.map(s => (
                                        <option key={s.id} value={s.id}>{s.nome}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black text-gray-400 tracking-widest ml-1">Sub-Sistema</label>
                                <select name="subSistemaId" className="w-full bg-background border border-border-color rounded-xl px-4 py-3.5 text-foreground font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none cursor-pointer">
                                    <option value="">Selecione o Sub-Sistema</option>
                                    {filteredSubSistemas.map((ss: OsSubSistema) => (
                                        <option key={ss.id} value={ss.id}>{ss.nome}</option>
                                    ))}
                                </select>
                            </div>
