'use client'

import { useState, useEffect } from 'react'
import { getPreventivaById, updatePreventiva, getVeiculosSimples } from '@/app/actions/preventiva-actions'
import { ArrowLeft, Save, Calendar, Clock, Settings, Wrench } from 'lucide-react'
import Link from 'next/link'
import { useParams, useRouter } from 'next/navigation'

interface VeiculoSimple {
    id: string;
    modelo: string;
    placa: string | null;
    codigoInterno: string;
    horimetroAtual: number;
    tipoVeiculo: string;
}

export default function EditarPreventivaPage() {
    const params = useParams()
    const router = useRouter()
    const id = params.id as string

    const [veiculos, setVeiculos] = useState<VeiculoSimple[]>([])
    const [loading, setLoading] = useState(false)
    const [initialLoading, setInitialLoading] = useState(true)

    const [formData, setFormData] = useState({
        veiculoId: '',
        tipo: '',
        modulo: '',
        ultimoHorimetro: 0,
        horimetroAtual: 0,
        intervalo: 500,
        dataAtualizacao: `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}-${String(new Date().getDate()).padStart(2, '0')}`
    })

    useEffect(() => {
        Promise.all([
            getVeiculosSimples(),
            getPreventivaById(id)
        ]).then(([veiculosData, preventivaData]) => {
            setVeiculos(veiculosData)

            if (preventivaData) {
                setFormData({
                    veiculoId: preventivaData.veiculoId,
                    tipo: preventivaData.tipo,
                    modulo: preventivaData.modulo || '',
                    ultimoHorimetro: preventivaData.ultimoHorimetro,
                    horimetroAtual: preventivaData.veiculo.horimetroAtual,
                    intervalo: preventivaData.intervalo,
                    dataAtualizacao: (() => {
                        const d = new Date(preventivaData.dataAtualizacao);
                        return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
                    })()
                })
            }

            setInitialLoading(false)
        })
    }, [id])

    const handleVeiculoChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const vId = e.target.value
        const v = veiculos.find(x => x.id === vId)
        setFormData(prev => ({
            ...prev,
            veiculoId: vId,
            horimetroAtual: v ? v.horimetroAtual : 0
        }))
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target
        setFormData(prev => ({ ...prev, [name]: value }))
    }

    if (initialLoading) {
        return <div className="p-8 text-center text-gray-500">Carregando dados...</div>
    }

    const selectedV = veiculos.find(v => v.id === formData.veiculoId)
    const isLeve = selectedV?.tipoVeiculo === 'LEVE'
    const unit = isLeve ? 'km' : 'h'
    const unitLabelSmall = isLeve ? 'Quilometragem' : 'Horímetro'

    return (
        <div className="max-w-2xl mx-auto py-6">
            <div className="mb-6">
                <Link href="/dashboard/pcm/preventivas" className="text-gray-500 hover:text-foreground text-sm flex items-center gap-1 mb-2 transition-colors">
                    <ArrowLeft className="w-4 h-4" /> Voltar
                </Link>
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-500/10 rounded-lg">
                        <Clock className="w-6 h-6 text-blue-500" />
                    </div>
                    <h1 className="text-2xl font-bold text-foreground">Editar Preventiva</h1>
                </div>
            </div>

            <div className="bg-surface border border-border-color rounded-xl p-6 shadow-lg">
                <form action={async (form) => {
                    setLoading(true)
                    await updatePreventiva(id, form)
                    setLoading(false)
                    router.push('/dashboard/pcm/preventivas')
                }} className="space-y-6">

                    {/* Hidden field for veiculoId since we disable select */}
                    <input type="hidden" name="veiculoId" value={formData.veiculoId} />

                    {/* Placa */}
                    <div className="space-y-2">
                        <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Placa / Veículo</label>
                        <select
                            name="veiculoId_display"
                            disabled
                            className="w-full bg-surface-highlight border border-border-color rounded-lg px-4 py-3 text-foreground opacity-60 cursor-not-allowed"
                            value={formData.veiculoId}
                        >
                            <option value="">Selecione o veículo</option>
                            {veiculos.map(v => (
                                <option key={v.id} value={v.id}>
                                    {v.codigoInterno} - {v.modelo} ({v.placa || 'Sem Placa'})
                                </option>
                            ))}
                        </select>
                        <p className="text-[10px] text-gray-400">* Não é possível alterar o veículo de uma preventiva já criada.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Tipo */}
                        <div className="space-y-2">
                            <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Tipo</label>
                            <div className="relative">
                                <Wrench className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                <input
                                    name="tipo"
                                    value={formData.tipo}
                                    onChange={handleChange}
                                    placeholder="Ex: Motor, Hidráulico"
                                    required
                                    className="w-full bg-surface-highlight border border-border-color rounded-lg pl-10 pr-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                                />
                            </div>
                        </div>

                        {/* Módulo */}
                        <div className="space-y-2">
                            <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Módulo</label>
                            <div className="relative">
                                <Settings className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                                <input
                                    name="modulo"
                                    value={formData.modulo}
                                    onChange={handleChange}
                                    placeholder="Ex: Sistema de Freio"
                                    className="w-full bg-surface-highlight border border-border-color rounded-lg pl-10 pr-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                                />
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Último Horímetro */}
                        <div className="space-y-2">
                            <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Última Revisão ({unit})</label>
                            <input
                                type="number"
                                name="ultimoHorimetro"
                                value={formData.ultimoHorimetro}
                                onChange={handleChange}
                                placeholder="0"
                                className="w-full bg-surface-highlight border border-border-color rounded-lg px-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                            />
                        </div>

                        {/* Horímetro Atual */}
                        <div className="space-y-2">
                            <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Atual ({unit})</label>
                            <input
                                type="number"
                                name="horimetroAtual"
                                value={formData.horimetroAtual}
                                onChange={handleChange}
                                className="w-full bg-surface-highlight border border-border-color rounded-lg px-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Intervalo ({unit})</label>
                        <input
                            type="number"
                            name="intervalo"
                            value={formData.intervalo}
                            onChange={handleChange}
                            required
                            className="w-full bg-surface-highlight border border-border-color rounded-lg px-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-xs uppercase font-bold text-gray-500 tracking-wider">Data da Atualização</label>
                        <div className="relative">
                            <input
                                type="date"
                                name="dataAtualizacao"
                                value={formData.dataAtualizacao}
                                onChange={handleChange}
                                className="w-full bg-surface-highlight border border-border-color rounded-lg px-4 py-3 text-foreground focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary appearance-none"
                            />
                            <Calendar className="absolute right-4 top-3.5 w-4 h-4 text-gray-400 pointer-events-none" />
                        </div>

                    </div>

                    <div className="pt-4 border-t border-border-color flex justify-end gap-3">
                        <Link href="/dashboard/pcm/preventivas">
                            <button type="button" className="px-6 py-3 rounded-lg border border-border-color text-gray-500 hover:text-foreground font-medium hover:bg-surface-highlight transition-colors">
                                Cancelar
                            </button>
                        </Link>
                        <button disabled={loading} type="submit" className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-lg font-bold flex items-center gap-2 transition-all shadow-lg shadow-blue-500/20 active:scale-95 disabled:opacity-50">
                            {loading ? 'Salvando...' : <><Save className="w-4 h-4" /> Salvar Alterações</>}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}

'use client'

import { useState, useEffect } from 'react'
import { updateSemanaPreventiva, getVeiculosSemanal, getWeekDates, updateWeekDates } from '@/app/actions/pcm-actions'
import { Truck, AlertCircle, CalendarClock, ChevronRight, GripVertical, CheckCircle2, X, LayoutDashboard, Share2, Loader2, RefreshCw, Save } from 'lucide-react'
import SemanalDashboard from './SemanalDashboard'

// --- Types ---
export interface Veiculo {
    id: string
    codigoInterno: string
    placa: string | null
    modelo: string
    tipoVeiculo: string
    semanaPreventiva: number | null
    status: string
    // New fields
    programacaoStatus?: string
    programacaoProgresso?: number
    programacaoModulo?: string
    programacaoDescricao?: string
    programacaoDataInicio?: string
    programacaoDataFim?: string
    moduloSistema?: string
}

interface ProgrammingDetails {
    status: string
    progresso: number
    modulo: string
    descricao: string
    dataInicio: string
    dataFim: string
    isPreventiva?: boolean
}

const DEFAULT_DETAILS: ProgrammingDetails = {
    status: 'PENDENTE',
    progresso: 0,
    modulo: '',
    descricao: '',
    dataInicio: '',
    dataFim: '',
    isPreventiva: false
}

export default function SemanalClient({ initialData, unidadeId }: { initialData: Veiculo[], unidadeId?: string }) {
    const [veiculos, setVeiculos] = useState<Veiculo[]>(initialData)
    const [draggedVeiculo, setDraggedVeiculo] = useState<string | null>(null)
    const [loadingId, setLoadingId] = useState<string | null>(null)
    const [isFetching, setIsFetching] = useState(false)
    const [filter, setFilter] = useState<string>('TODOS')
    const [view, setView] = useState<'BOARD' | 'DASHBOARD'>('BOARD')

    // Period Filter State (Default to current month)
    const [startDate, setStartDate] = useState(() => {
        const d = new Date()
        return new Date(d.getFullYear(), d.getMonth(), 1).toISOString().split('T')[0]
    })
    const [endDate, setEndDate] = useState(() => {
        const d = new Date()
        return new Date(d.getFullYear(), d.getMonth() + 1, 0).toISOString().split('T')[0]
    })

    // State for dates of each specific week
    const [weekDates, setWeekDates] = useState<Record<number, { start: string, end: string }>>(() => {
        const dates: Record<number, { start: string, end: string }> = {}
        const today = new Date()

        // Helper to get Monday of current week
        const monday = new Date(today);
        const day = today.getDay();
        const diff = today.getDate() - day + (day === 0 ? -6 : 1);
        monday.setDate(diff);

        for (let i = 1; i <= 4; i++) {
            const start = new Date(monday);
            start.setDate(monday.getDate() + (i - 1) * 7);

            const end = new Date(start);
            end.setDate(start.getDate() + 6);

            dates[i] = {
                start: start.toISOString().split('T')[0],
                end: end.toISOString().split('T')[0]
            }
        }
        return dates
    })
    const [isSavingDates, setIsSavingDates] = useState(false)

    // Load persisted dates on mount
    useEffect(() => {
        const loadDates = async () => {
            const saved = await getWeekDates()
            if (saved) {
                setWeekDates(saved)
            }
        }
        loadDates()
    }, [])


    const handleSaveWeekDates = async () => {
        setIsSavingDates(true)
        try {
            const res = await updateWeekDates(weekDates)
            if (res.success) {
                alert("Ciclo de datas salvo com sucesso!")
            } else {
                alert(res.error || "Erro ao salvar datas")
            }
        } catch (e) {
            alert("Erro ao conectar com o servidor")
        } finally {
            setIsSavingDates(false)
        }
    }

    // Modal State
    const [isModalOpen, setIsModalOpen] = useState(false)
    const [pendingDrop, setPendingDrop] = useState<{ veiculoId: string, week: number } | null>(null)
    const [details, setDetails] = useState<ProgrammingDetails>(DEFAULT_DETAILS)

    // Auto-calculate progress
    useEffect(() => {
        if (details.status === 'PENDENTE' || details.status === 'CANCELADO') {
            setDetails(prev => ({ ...prev, progresso: 0 }))
        } else if (details.status === 'CONCLUIDO') {
            setDetails(prev => ({ ...prev, progresso: 100 }))
        } else if (details.status === 'EM_ANDAMENTO') {
            // Optional: Time-based calculation for fun/tech-demo, but keep it clear
            if (details.dataInicio && details.dataFim) {
                const start = new Date(details.dataInicio).getTime()
                const end = new Date(details.dataFim).getTime()
                const now = new Date().getTime()
                const total = end - start

                if (total > 0) {
                    const elapsed = now - start
                    let p = Math.round((elapsed / total) * 100)
                    if (p < 0) p = 0
                    if (p > 95) p = 95 // Cap at 95 until marked done
                    setDetails(prev => ({ ...prev, progresso: p }))
                } else {
                    // Default if dates invalid/same
                    setDetails(prev => ({ ...prev, progresso: 50 }))
                }
            } else {
                setDetails(prev => ({ ...prev, progresso: 50 }))
            }
        }
    }, [details.status, details.dataInicio, details.dataFim])

    const handleDragStart = (e: React.DragEvent, veiculoId: string) => {
        e.dataTransfer.setData('veiculoId', veiculoId)
        setDraggedVeiculo(veiculoId)
    }

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault()
    }

    const handleDrop = async (e: React.DragEvent, targetWeek: number | null) => {
        e.preventDefault()
        const veiculoId = e.dataTransfer.getData('veiculoId')

        if (!veiculoId || loadingId) return

        const currentVeiculo = veiculos.find(v => v.id === veiculoId)
        if (currentVeiculo?.semanaPreventiva === targetWeek) return

        // If dropping into "Sem Programação" (null), execute immediately without info
        if (targetWeek === null) {
            executeMove(veiculoId, null, undefined)
            return
        }

        // If dropping into a week, open modal to get details
        setPendingDrop({ veiculoId, week: targetWeek })

        // Pre-fill existing data if available, or defaults
        const weekInfo = weekDates[targetWeek]
        setDetails({
            status: currentVeiculo?.programacaoStatus || 'PENDENTE',
            progresso: currentVeiculo?.programacaoProgresso || 0,
            modulo: currentVeiculo?.programacaoModulo || currentVeiculo?.moduloSistema || '',
            descricao: currentVeiculo?.programacaoDescricao || '',
            dataInicio: currentVeiculo?.programacaoDataInicio
                ? new Date(currentVeiculo.programacaoDataInicio).toISOString().split('T')[0]
                : (weekInfo?.start || ''),
            dataFim: currentVeiculo?.programacaoDataFim
                ? new Date(currentVeiculo.programacaoDataFim).toISOString().split('T')[0]
                : (weekInfo?.end || ''),
            isPreventiva: currentVeiculo?.programacaoModulo === 'MPBT'
        })

        setIsModalOpen(true)
    }

    const confirmProgramming = async () => {
        if (!pendingDrop) return

        await executeMove(pendingDrop.veiculoId, pendingDrop.week, details)
        setIsModalOpen(false)
        setPendingDrop(null)
    }

    const executeMove = async (veiculoId: string, targetWeek: number | null, extraDetails?: ProgrammingDetails) => {
        const currentVeiculo = veiculos.find(v => v.id === veiculoId)

        // Optimistic update
        setVeiculos(prev => prev.map(v =>
            v.id === veiculoId ? {
                ...v,
                semanaPreventiva: targetWeek,
                ...(extraDetails ? {
                    programacaoStatus: extraDetails.status,
                    programacaoProgresso: extraDetails.progresso,
                    programacaoModulo: extraDetails.modulo,
                    programacaoDescricao: extraDetails.descricao,
                    programacaoDataInicio: extraDetails.dataInicio, // Simple string storage for optimistic
                    programacaoDataFim: extraDetails.dataFim
                } : {})
            } : v
        ))
        setLoadingId(veiculoId)

        try {
            const result = await updateSemanaPreventiva(veiculoId, targetWeek, extraDetails)
            if (!result.success) {
                // Revert
                setVeiculos(prev => prev.map(v =>
                    v.id === veiculoId ? {
                        ...v,
                        semanaPreventiva: currentVeiculo?.semanaPreventiva ?? null,
                        programacaoStatus: currentVeiculo?.programacaoStatus,
                        programacaoProgresso: currentVeiculo?.programacaoProgresso
                        // ... revert others if needed strictly
                    } : v
                ))
            }
        } catch (error) {
            console.error('Failed to update week', error)
        } finally {
            setLoadingId(null)
            setDraggedVeiculo(null)
        }
    }

    const handleRefresh = async () => {
        setIsFetching(true)
        try {
            const data = await getVeiculosSemanal({ startDate, endDate })
            setVeiculos(data)
        } catch (error) {
            console.error('Failed to fetch filtered data', error)
        } finally {
            setIsFetching(false)
        }
    }

    const getColumnVehicles = (week: number | null) => {
        return veiculos
            .filter(v => v.semanaPreventiva === week)
            .filter(v => filter === 'TODOS' || v.tipoVeiculo === filter)
    }

    const handleShare = () => {
        if (!unidadeId) {
            alert("Não foi possível identificar a unidade para gerar o link.")
            return
        }
        const url = `${window.location.origin}/share/pcm/semanal?u=${unidadeId}`
        navigator.clipboard.writeText(url)
        alert("Link de visitante copiado para a área de transferência!")
    }

    const weeks = [
        { id: 1, label: 'Semana 1', color: 'border-l-blue-500', bg: 'bg-blue-500/5' },
        { id: 2, label: 'Semana 2', color: 'border-l-emerald-500', bg: 'bg-emerald-500/5' },
        { id: 3, label: 'Semana 3', color: 'border-l-orange-500', bg: 'bg-orange-500/5' },
        { id: 4, label: 'Semana 4', color: 'border-l-purple-500', bg: 'bg-purple-500/5' },
    ]

    if (view === 'DASHBOARD') {
        return <SemanalDashboard
            veiculos={veiculos}
            startDate={startDate}
            endDate={endDate}
            onBack={() => setView('BOARD')}
        />
    }

    return (
        <div className="h-full flex flex-col relative">
            {/* Header */}
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-black tracking-tight text-foreground flex items-center gap-2">
                        <CalendarClock className="w-6 h-6 text-primary" />
                        Programação Semanal
                    </h2>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-widest mt-1">
                        Distribuição da Frota por Ciclo
                    </p>
                </div>
                <div className="flex items-center gap-4">
                    {/* Period Filter */}
                    <div className="flex items-center gap-3 bg-surface-highlight/50 border border-border-color rounded-2xl px-4 py-2">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Início</span>
                            <input
                                type="date"
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                className="bg-transparent text-xs font-bold text-foreground outline-none border-b border-transparent focus:border-primary transition-all cursor-pointer"
                            />
                        </div>
                        <div className="w-px h-6 bg-border-color mx-1" />
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Fim</span>
                            <input
                                type="date"
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                className="bg-transparent text-xs font-bold text-foreground outline-none border-b border-transparent focus:border-primary transition-all cursor-pointer"
                            />
                        </div>
                        <button
                            onClick={handleRefresh}
                            disabled={isFetching}
                            className={`ml-2 p-1.5 bg-primary/10 text-primary rounded-lg hover:bg-primary/20 transition-all ${isFetching ? 'animate-spin' : ''}`}
                            title="Filtrar Período"
                        >
                            {isFetching ? <Loader2 className="w-4 h-4" /> : <RefreshCw className="w-4 h-4" />}
                        </button>
                    </div>

                    <button
                        onClick={handleSaveWeekDates}
                        disabled={isSavingDates}
                        className={`flex items-center gap-2 px-3 py-2 bg-emerald-500/10 text-emerald-600 border border-emerald-500/20 rounded-lg text-xs font-black uppercase tracking-widest hover:bg-emerald-500/20 transition-colors ${isSavingDates ? 'opacity-50 cursor-not-allowed' : ''}`}
                        title="Salvar Datas das Semanas"
                    >
                        {isSavingDates ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        Salvar Ciclo
                    </button>

                    <button
                        onClick={() => setView('DASHBOARD')}
                        className="flex items-center gap-2 px-3 py-2 bg-purple-500/10 text-purple-600 border border-purple-500/20 rounded-lg text-xs font-black uppercase tracking-widest hover:bg-purple-500/20 transition-colors"
                    >
                        <LayoutDashboard className="w-4 h-4" />
                        Dashboard
                    </button>

                    <button
                        onClick={handleShare}
                        className="flex items-center gap-2 px-3 py-2 bg-blue-500/10 text-blue-600 border border-blue-500/20 rounded-lg text-xs font-black uppercase tracking-widest hover:bg-blue-500/20 transition-colors"
                        title="Link para Visitante (Visualização)"
                    >
                        <Share2 className="w-4 h-4" />
                        Compartilhar
                    </button>

                    <div className="flex bg-surface-highlight rounded-lg p-1 border border-border-color">
                        {['TODOS', 'LEVE', 'PESADO'].map((type) => (
                            <button
                                key={type}
                                onClick={() => setFilter(type)}
                                className={`
                                    px-3 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-md transition-all
                                    ${filter === type ? 'bg-primary text-white shadow-sm' : 'text-gray-500 hover:text-foreground hover:bg-surface'}
                                `}
                            >
                                {type === 'TODOS' ? 'Todos' : type}
                            </button>
                        ))}
                    </div>
                    <div className="bg-surface border border-border-color px-4 py-2 rounded-xl flex items-center gap-2 text-xs font-bold text-gray-500">
                        <AlertCircle className="w-4 h-4 text-yellow-500" />
                        Arraste para programar
                    </div>
                </div>
            </div>

            {/* Board */}
            <div className="flex-1 grid grid-cols-5 gap-4 min-h-0 overflow-hidden">
                {/* Unscheduled Column */}
                <div
                    className="bg-surface border border-border-color rounded-2xl flex flex-col h-full overflow-hidden"
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, null)}
                >
                    <div className="p-4 border-b border-border-color bg-surface-highlight/20 sticky top-0 z-10 backdrop-blur-sm">
                        <div className="flex justify-between items-center">
                            <span className="text-xs font-black uppercase tracking-widest text-gray-500">Sem Programação</span>
                            <span className="bg-gray-500/10 text-gray-500 px-2 py-0.5 rounded-md text-[10px] font-black">
                                {getColumnVehicles(null).length}
                            </span>
                        </div>
                    </div>
                    <div className="p-3 flex-1 overflow-y-auto custom-scrollbar space-y-2">
                        {getColumnVehicles(null).map(veiculo => (
                            <VehicleCard
                                key={veiculo.id}
                                veiculo={veiculo}
                                onDragStart={handleDragStart}
                                isLoading={loadingId === veiculo.id}
                            />
                        ))}
                        {getColumnVehicles(null).length === 0 && (
                            <div className="h-20 flex items-center justify-center text-gray-400 text-xs font-bold italic opacity-50 border-2 border-dashed border-border-color rounded-xl">
                                Vazio
                            </div>
                        )}
                    </div>
                </div>

                {/* Weeks Columns */}
                {weeks.map(week => (
                    <div
                        key={week.id}
                        className={`bg-surface border border-border-color rounded-2xl flex flex-col h-full overflow-hidden ${draggedVeiculo ? 'border-dashed border-primary/30' : ''}`}
                        onDragOver={handleDragOver}
                        onDrop={(e) => handleDrop(e, week.id)}
                    >
                        <div className={`p-4 border-b border-border-color ${week.bg} sticky top-0 z-10 backdrop-blur-sm space-y-3`}>
                            <div className="flex justify-between items-center">
                                <span className="text-xs font-black uppercase tracking-widest text-foreground">{week.label}</span>
                                <span className="bg-surface text-foreground px-2 py-0.5 rounded-md text-[10px] font-black shadow-sm">
                                    {getColumnVehicles(week.id).length}
                                </span>
                            </div>

                            {/* Per-week Date Range Picker */}
                            <div className="flex flex-col gap-1.5 p-2 bg-white/40 dark:bg-black/10 rounded-xl border border-white/50 dark:border-white/5">
                                <div className="flex items-center justify-between gap-2">
                                    <div className="flex flex-col flex-1">
                                        <span className="text-[8px] font-black uppercase text-gray-400">Início</span>
                                        <input
                                            type="date"
                                            value={weekDates[week.id]?.start || ''}
                                            onChange={(e) => setWeekDates(prev => ({
                                                ...prev,
                                                [week.id]: { ...prev[week.id], start: e.target.value }
                                            }))}
                                            className="bg-transparent text-[10px] font-bold text-foreground outline-none border-b border-transparent focus:border-primary transition-all p-0 h-4"
                                        />
                                    </div>
                                    <div className="w-px h-4 bg-gray-300/30 self-end mb-1" />
                                    <div className="flex flex-col flex-1">
                                        <span className="text-[8px] font-black uppercase text-gray-400">Fim</span>
                                        <input
                                            type="date"
                                            value={weekDates[week.id]?.end || ''}
                                            onChange={(e) => setWeekDates(prev => ({
                                                ...prev,
                                                [week.id]: { ...prev[week.id], end: e.target.value }
                                            }))}
                                            className="bg-transparent text-[10px] font-bold text-foreground outline-none border-b border-transparent focus:border-primary transition-all p-0 h-4"
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="p-3 flex-1 overflow-y-auto custom-scrollbar space-y-2 relative">
                            {/* Guide Lines */}
                            <div className={`absolute inset-0 pointer-events-none opacity-[0.02] bg-[radial-gradient(#000_1px,transparent_1px)] [background-size:16px_16px]`} />

                            {getColumnVehicles(week.id).map(veiculo => (
                                <VehicleCard
                                    key={veiculo.id}
                                    veiculo={veiculo}
                                    onDragStart={handleDragStart}
                                    weekId={week.id}
                                    isLoading={loadingId === veiculo.id}
                                    onQuickAction={(status, moveNext) => {
                                        const currentDetails: ProgrammingDetails = {
                                            status: status || veiculo.programacaoStatus || 'PENDENTE',
                                            progresso: status === 'CONCLUIDO' ? 100 : (status === 'EM_ANDAMENTO' ? 50 : (status === 'PENDENTE' ? 0 : (veiculo.programacaoProgresso || 0))),
                                            modulo: veiculo.programacaoModulo || veiculo.moduloSistema || '',
                                            descricao: veiculo.programacaoDescricao || '',
                                            dataInicio: veiculo.programacaoDataInicio ? new Date(veiculo.programacaoDataInicio).toISOString().split('T')[0] : '',
                                            dataFim: veiculo.programacaoDataFim ? new Date(veiculo.programacaoDataFim).toISOString().split('T')[0] : ''
                                        }

                                        const nextWeek = moveNext ? Math.min((week.id || 0) + 1, 4) : week.id
                                        executeMove(veiculo.id, nextWeek, currentDetails)
                                    }}
                                />
                            ))}
                            {getColumnVehicles(week.id).length === 0 && (
                                <div className="h-full flex flex-col items-center justify-center text-gray-400 text-xs font-bold opacity-30">
                                    <span className="text-2xl mb-2">📅</span>
                                    <span>Arraste aqui</span>
                                </div>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* Programming Dialog */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
                    <div className="bg-surface border border-border-color w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                        <div className="p-4 border-b border-border-color flex justify-between items-center bg-surface-highlight/10">
                            <h3 className="text-lg font-black tracking-tight text-foreground flex items-center gap-2">
                                <CheckCircle2 className="w-5 h-5 text-primary" />
                                Detalhes da Programação
                            </h3>
                            <button onClick={() => setIsModalOpen(false)} className="text-gray-500 hover:text-red-500 transition-colors">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4">
                            <div className="flex items-center gap-2 p-3 bg-primary/5 border border-primary/10 rounded-xl mb-4">
                                <input
                                    type="checkbox"
                                    id="preventiva"
                                    checked={details.isPreventiva}
                                    onChange={e => {
                                        const checked = e.target.checked
                                        setDetails(prev => ({
                                            ...prev,
                                            isPreventiva: checked,
                                            modulo: checked ? 'MPBT' : prev.modulo,
                                            descricao: checked ? 'PLANO DE MANUTENÇÃO ( )' : prev.descricao
                                        }))
                                    }}
                                    className="w-4 h-4 rounded border-gray-300 text-primary focus:ring-primary cursor-pointer"
                                />
                                <label htmlFor="preventiva" className="text-xs font-black uppercase text-primary cursor-pointer select-none">
                                    Manutenção Preventiva (MPBT)
                                </label>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black uppercase text-gray-500 ml-1">Status</label>
                                    <select
                                        value={details.status}
                                        onChange={e => setDetails(prev => ({ ...prev, status: e.target.value }))}
                                        className="w-full bg-surface-highlight border border-border-color rounded-xl px-3 py-2 text-xs font-bold outline-none focus:border-primary transition-colors"
                                    >
                                        <option value="PENDENTE">Pendente</option>
                                        <option value="EM_ANDAMENTO">Em Andamento</option>
                                        <option value="CONCLUIDO">Concluído</option>
                                        <option value="CANCELADO">Cancelado</option>
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black uppercase text-gray-500 ml-1">Progresso (%)</label>
                                    <input
                                        type="number"
                                        min="0" max="100"
                                        readOnly
                                        value={details.progresso}
                                        className="w-full bg-surface border border-border-color rounded-xl px-3 py-2 text-xs font-bold outline-none text-gray-500 cursor-not-allowed"
                                        title="Calculado automaticamente pelo status e datas"
                                    />
                                </div>
                            </div>

                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black uppercase text-gray-500 ml-1">Módulo / Setor</label>
                                <input
                                    value={details.modulo}
                                    placeholder="Ex: MÓDULO 05"
                                    onChange={e => setDetails(prev => ({ ...prev, modulo: e.target.value }))}
