  const imagesRef = useRef<HTMLImageElement[]>([]);

  useEffect(() => {
    let imagesLoaded = 0;
    const images: HTMLImageElement[] = [];
    let isMounted = true;

    for (let i = 0; i < TOTAL_FRAMES; i++) {
      const img = new window.Image();
      img.src = `${FRAME_PREFIX}${String(i).padStart(3, '0')}.jpg`;
      img.onload = () => {
        if (!isMounted) return;
        imagesLoaded++;
        if (imagesLoaded === TOTAL_FRAMES) {
          setLoaded(true);
        }
      };
      images.push(img);
    }
    imagesRef.current = images;

    return () => {
      isMounted = false;
    };
  }, []);

  useEffect(() => {
    if (!loaded) return;

    let lastTime = performance.now();
    const interval = 1000 / 12; // ~12 fps (very smooth and slow)
    let reqId: number;

    const animate = (time: number) => {
      if (time - lastTime >= interval) {
        setFrame(prev => (prev + 1) % TOTAL_FRAMES);
        lastTime = time;
      }
      reqId = requestAnimationFrame(animate);
    };

    reqId = requestAnimationFrame(animate);

    return () => cancelAnimationFrame(reqId);
  }, [loaded]);

  const currentSrc = loaded ? `${FRAME_PREFIX}${String(frame).padStart(3, '0')}.jpg` : '/logo.png';

  return (
    <img
      src={currentSrc}
      alt="Eunaman Logo Animation"
      className={`object-contain mix-blend-multiply ${className}`}
      style={fill ? { width: '100%', height: '100%', position: 'absolute', inset: 0 } : { width, height }}
    />
  );
}

const { PrismaClient } = require('@prisma/client')
const prisma = new PrismaClient()

async function main() {
    try {
        console.log('Testing connection...')
        const userCount = await prisma.usuario.count()
        console.log('Connection successful! User count:', userCount)
    } catch (e) {
        console.error('Connection failed!')
        console.error(e)
    } finally {
        await prisma.$disconnect()
    }
}

